def get_kb_data(client_id=None):
    if not cache.get("kb_by_cid"):
        rebuild_kb_index()
    if client_id:
        return cache.get("kb_by_cid", {}).get(client_id, [])
    raw = cache.get("kb", DEFAULT_KB)
    if not isinstance(raw, list):
        return []
    return raw

def get_rules_data(client_id=None):
    if not cache.get("rules_by_cid"):
        rebuild_rules_index()
    if client_id:
        return cache.get("rules_by_cid", {}).get(client_id, [])
    return cache.get("rules", DEFAULT_RULES)

def get_client_prompt(cid):
    """Return the raw, editable brand prompt for a specific client (no name suffix).
    Falls back to the global/default prompt if the client has none of its own yet."""
    prompts = cache.get("prompts") or {}
    val = prompts.get(cid)
    if val and str(val).strip():
        return val
    return cache.get("prompt", DEFAULT_SYSTEM_PROMPT)

def get_client_mode(cid):
    """Return the auto/manual reply mode for a specific client.
    Falls back to the global approval_mode when the client has no explicit setting."""
    modes = cache.get("client_modes") or {}
    m = modes.get(cid)
    if m in ("auto", "manual"):
        return m
    return cache.get("approval_mode", "auto")

