@app.route("/api/data-deletion", methods=["POST", "GET"])
def api_data_deletion():
    data = request.get_json(silent=True) or request.form or {}
    signed_req = data.get("signed_request", "")

    # Extract Meta user_id from the signed_request payload (base64url of "sig.payload")
    user_id = None
    if signed_req and "." in signed_req:
        try:
            payload_b64 = signed_req.split(".", 1)[1]
            payload_b64 += "=" * (-len(payload_b64) % 4)
            payload = json.loads(base64.urlsafe_b64decode(payload_b64))
            user_id = payload.get("user_id")
        except Exception as e:
            print(f"[DataDeletion] parse error: {e}")
    if not user_id:
        user_id = str(abs(hash(signed_req)))[-8:]

    # Actually purge this user's stored conversation data
    global activity_log, pending_approvals
    before = len(activity_log)
    activity_log = [e for e in activity_log if str(e.get("sender")) != str(user_id)]
    pending_approvals = [p for p in pending_approvals if str(p.get("sender")) != str(user_id)]
    purged = before - len(activity_log)
    print(f"[DataDeletion] purged {purged} records for user {user_id}")

    confirm_code = f"DEL-{user_id}-{int(time.time())}"
    return jsonify({
        "url": f"https://metaaimoderator.vercel.app/deletion-status?id={user_id}",
        "confirmation_code": confirm_code
    })

