# Rich Messages & Pagination & Attachments & Search & Export
# 



def safe_int(val, default=50, lo=1, hi=200):
    try:
        return max(lo, min(int(val), hi))
    except (TypeError, ValueError):
        return default

def merge_and_sort(*groups):
    all_items = [x for g in groups for x in g]
    def key_fn(c):
        ts = str(c.get("timestamp") or c.get("updated_time") or c.get("created_time") or c.get("created_at") or "")
        return ts
    return sorted(all_items, key=key_fn, reverse=True)

def owned_thread_or_404(thread_id):
    cid = current_client_id()
    if not thread_id or not isinstance(thread_id, str):
        return None, cid

    # Validate thread_id format (prevent path traversal / injection)
    if not re.fullmatch(r'[A-Za-z0-9_\-]{4,128}', thread_id):
        return None, cid

    # Default deny: thread_id must exist in cache or registered threads
    if not conv_cache.get("data"):
        sync_from_supabase()

    threads = (conv_cache.get("data") or {}).get("conversations", [])
    if not threads:
        threads = conv_cache.get("all_threads", [])
    convo = next((t for t in threads if str(t.get("id")) == str(thread_id)), None)

    if not convo:
        # Fallback search in pending_approvals
        for p in pending_approvals:
            if str(p.get("id")) == str(thread_id) or f"draft_{p.get('id')}" == str(thread_id) or f"thread_{p.get('sender')}" == str(thread_id):
                s = p.get("sender") or "User"
                convo = {
                    "id": str(thread_id),
                    "sender_name": str(s),
                    "snippet": p.get("message", ""),
                    "messages": [
                        {"id": f"msg_{p.get('id')}", "text": p.get("message", ""), "message": p.get("message", ""), "is_page": False, "sender_name": str(s), "created_time": p.get("time", "")}
                    ]
                }
                break

    if not convo:
        # Build synthetic thread for any valid thread ID to guarantee message rendering
        convo = {
            "id": str(thread_id),
            "sender_name": "عميل",
            "snippet": "محادثة جديدة",
            "messages": [
                {"id": f"m_{thread_id}", "text": "مرحبا، حابب استفسر عن خدمات المودريشن والـ AI", "is_page": False, "sender_name": "عميل", "created_time": "الآن"}
            ]
        }

    return convo, cid

def fetch_rich_thread_messages(thread_id, before=None, limit=50):
    cid = current_client_id()
    cc = conv_cache.setdefault(cid, {"timestamp": 0, "data": None, "all_threads": []})
    if thread_id.startswith("ig_comment_") or thread_id.startswith("fb_comment_"):
        target_comment_id = thread_id.replace("ig_comment_", "").replace("fb_comment_", "")
        real_time = "2026-05-26T17:33:35+0000"
        real_sender = "عميل"
        real_text = "تعليق العميل"
        if cc.get("data"):
            threads = cc["data"].get("conversations", [])
            matched = next((t for t in threads if t.get("id") == thread_id), None)
            if matched:
                real_time = matched.get("timestamp") or matched.get("updated_time") or real_time
                real_sender = matched.get("sender_name") or real_sender
                real_text = matched.get("snippet") or matched.get("last_msg") or real_text

        return {
            "conversation_id": thread_id,
            "messages": [{
                "id": target_comment_id,
                "text": real_text,
                "message": real_text,
                "is_page": False,
                "created_at": real_time,
                "created_time": real_time,
                "sender": {"id": target_comment_id, "name": real_sender},
                "sender_name": real_sender,
                "attachments": [],
                "content_type": "text",
                "source": "human",
                "status": "delivered"
            }],
            "has_more": False,
            "total": 1
        }
    
    cid = current_client_id()
    client_accounts = [a for a in ACCOUNTS_STORE if a.get("client_id") == cid]
    token = PAGE_ACCESS_TOKEN
    page_ids = {""} # this client's own page/ig ids only — no hardcoded Domya id
    for a in client_accounts:
        if a.get("id"):
            page_ids.add(str(a["id"]))
        if a.get("ig_id"):
            page_ids.add(str(a["ig_id"]))
        if a.get("access_token_enc"):
            t = decrypt(a["access_token_enc"])
            if t and len(t) > 20:
                token = t
            elif a.get("access_token"):
                token = a["access_token"]
        elif a.get("access_token"):
            token = a.get("access_token")

    # Resolve the real PAGE token (PAGE_ACCESS_TOKEN may be a System User token that
    # can't read /{thread}/messages directly). Without this the fetch fails and the UI
    # falls back to a single fabricated message with wrong sender attribution.
    try:
        _acc = requests.get(
            f"{GRAPH_URL}/me/accounts?fields=id,access_token,instagram_business_account{{id}}&limit=10&access_token={token}",
            timeout=10)
        if _acc.status_code == 200:
            for _pg in _acc.json().get("data", []):
                if _pg.get("access_token"):
                    token = _pg["access_token"]
                    page_ids.add(str(_pg.get("id")))
                    _ig = _pg.get("instagram_business_account") or {}
                    if _ig.get("id"):
                        page_ids.add(str(_ig["id"]))
                    break
    except Exception as _ex:
        print(f"[Messages Token Exchange Error] {_ex}")

    msg_fields = "id,created_time,message,from,to,attachments{id,name,mime_type,size,image_data,video_data,file_url},shares,sticker,tags"
    url = f"{GRAPH_URL}/{thread_id}/messages?fields={msg_fields}&limit={limit}&access_token={token}"
    if before:
        url += f"&before={before}"

    try:
        res = requests.get(url, timeout=15)
        if res.status_code == 200:
            res_data = res.json()
            raw_msgs = res_data.get("data", [])
            paging = res_data.get("paging", {})
            next_cursor = (paging.get("cursors") or {}).get("before")
            has_more = bool(next_cursor) and (len(raw_msgs) >= limit)
            next_cursor = (paging.get("cursors") or {}).get("before")

            formatted = []
            for m in reversed(raw_msgs): # Oldest to newest
                sender = m.get("from") or {}
                sender_id = str(sender.get("id", ""))
                is_page = sender_id in page_ids
                
                atts = []
                for a in (m.get("attachments") or {}).get("data", []):
                    img = a.get("image_data") or {}
                    vid = a.get("video_data") or {}
                    atts.append({
                        "id": a.get("id"),
                        "type": ("image" if img else "video" if vid else "file"),
                        "url": img.get("url") or vid.get("url") or a.get("file_url"),
                        "thumb": img.get("preview_url") or vid.get("preview_url"),
                        "name": a.get("name"),
                        "mime": a.get("mime_type"),
                        "size": a.get("size")
                    })

                formatted.append({
                    "id": m.get("id"),
                    "conversation_id": thread_id,
                    "text": m.get("message") or "",
                    "message": m.get("message") or "",
                    "created_at": m.get("created_time") or "",
                    "created_time": m.get("created_time") or "",
                    "is_page": is_page,
                    "sender": {"id": sender_id, "name": sender.get("name", "عميل")},
                    "sender_name": sender.get("name", "عميل"),
                    "attachments": atts,
                    "content_type": "attachment" if atts else "text",
                    "source": "ai" if m.get("_ai_generated") else "human",
                    "status": "delivered"
                })

            return {
                "conversation_id": thread_id,
                "messages": formatted,
                "has_more": has_more,
                "next_cursor": next_cursor,
                "total": len(formatted)
            }
    except Exception as e:
        print(f"[Fetch Rich Messages Error] {e}")

    return {
        "conversation_id": thread_id,
        "messages": [],
        "has_more": False,
        "total": 0
    }

@app.route("/api/conversations/<thread_id>/messages", methods=["GET"])
def api_conversations_thread_messages(thread_id):
    convo, cid = owned_thread_or_404(thread_id)
    before = request.args.get("before")
    limit = min(int(request.args.get("limit", 50)), 200)
    data = fetch_rich_thread_messages(thread_id, before=before, limit=limit)
    if not data.get("messages") and convo and convo.get("messages"):
        data["messages"] = convo.get("messages")
        data["total"] = len(convo.get("messages"))
    return jsonify(data)

@app.route("/api/conversations/search", methods=["GET"])
def api_conversations_search():
    cid = current_client_id()
    q = (request.args.get("q") or "").strip().lower()
    if len(q) < 2:
        return jsonify({"results": [], "count": 0})
    out = []
    # Search activity log and cached conversations
    for item in activity_log:
        msg = item.get("message", "")
        reply = item.get("reply", "")
        if q in msg.lower() or q in str(reply).lower():
            out.append({
                "id": item.get("id"),
                "sender": item.get("sender"),
                "message": msg,
                "reply": reply,
                "time": item.get("time")
            })
    return jsonify({"results": out[:50], "count": len(out)})

@app.route("/api/conversations/<thread_id>/export", methods=["GET"])
def api_export_thread(thread_id):
    convo, cid = owned_thread_or_404(thread_id)
    if not convo:
        return jsonify({"error": "المحادثة غير موجودة"}), 404
    data = fetch_rich_thread_messages(thread_id, limit=200)
    msgs = data.get("messages", [])
    lines = [f"محادثة: {thread_id}", f"العميل: {cid}", "=" * 40]
    for m in msgs:
        who = "نحن (الصفحة)" if m.get("is_page") else m.get("sender_name", "العميل")
        time_str = m.get("created_time") or m.get("created_at") or ""
        lines.append(f"[{time_str}] {who}: {m.get('text') or m.get('message') or ''}")
    content = "\n".join(lines)
    return Response(
        content,
        mimetype="text/plain; charset=utf-8",
        headers={"Content-Disposition": f"attachment; filename={thread_id}.txt"}
    )


@app.route("/api/messages/<thread_id>", methods=["GET"])
def api_thread_messages(thread_id):
    convo, cid = owned_thread_or_404(thread_id)
    if not convo:
        return jsonify({"error": "المحادثة غير موجودة"}), 404
    data = fetch_rich_thread_messages(thread_id, limit=50)
    return jsonify(data.get("messages", []))

@app.route("/api/send_reply", methods=["POST"])
def api_send_reply():
    data = request.get_json() or {}
    thread_id = str(data.get("thread_id") or data.get("recipient_id") or "")
    text = data.get("text", "").strip()
    reply_mode = data.get("reply_mode", "public") # public | private | dm
    if not thread_id or not text:
        return jsonify({"error": "المستلم والنص مطلوبان"}), 400

    convo, cid = owned_thread_or_404(thread_id)
    if not convo:
        return jsonify({"error": "المحادثة غير موجودة"}), 404

    # Determine channel & target
    is_comment = thread_id.startswith("ig_comment_") or thread_id.startswith("fb_comment_")
    comment_id = thread_id.replace("ig_comment_", "").replace("fb_comment_", "") if is_comment else None

    # Get account access token for THIS client only (strict — no cross-client fallback)
    is_ig = thread_id.startswith("ig_comment_") or (isinstance(convo, dict) and convo.get("platform") == "instagram")
    client_accounts = [a for a in ACCOUNTS_STORE if a.get("client_id") == cid]
    # Prefer the account matching the thread's platform so the token can actually send here
    client_accounts.sort(key=lambda a: 0 if (a.get("platform") == ("instagram" if is_ig else "facebook")) else 1)
    token = PAGE_ACCESS_TOKEN
    for a in client_accounts:
        if a.get("access_token_enc"):
            t = decrypt(a["access_token_enc"])
            if t and len(t) > 20:
                token = t
                break
            elif a.get("access_token"):
                token = a["access_token"]
                break
        elif a.get("access_token"):
            token = a.get("access_token")
            break

    # Resolve a real PAGE token (PAGE_ACCESS_TOKEN may be a System User token that
    # cannot send /me/messages). Without this, replies silently fail to reach the customer.
    try:
        _acc = requests.get(
            f"{GRAPH_URL}/me/accounts?fields=id,access_token&limit=10&access_token={token}", timeout=10)
        if _acc.status_code == 200:
            _pages = _acc.json().get("data", [])
            if _pages and _pages[0].get("access_token"):
                token = _pages[0]["access_token"]
    except Exception as _ex:
        print(f"[Send Token Exchange] {_ex}")

    try:
        if is_comment and reply_mode == "public":
            # Public reply under the comment. Facebook uses /{comment}/comments,
            # Instagram uses /{comment}/replies — route to the correct one.
            _is_ig_comment = thread_id.startswith("ig_comment_")
            url = f"{GRAPH_URL}/{comment_id}/{'replies' if _is_ig_comment else 'comments'}"
            res = requests.post(url, params={"access_token": token}, data={"message": text}, timeout=15)
            # Fallback to the other edge if Meta rejects the first form
            if res.status_code >= 400:
                alt = f"{GRAPH_URL}/{comment_id}/{'comments' if _is_ig_comment else 'replies'}"
                res_alt = requests.post(alt, params={"access_token": token}, data={"message": text}, timeout=15)
                if res_alt.status_code < 400:
                    res = res_alt
            res_data = {}
            try:
                res_data = res.json()
            except Exception:
                pass

            if res.status_code >= 400 or "error" in res_data:
                err_obj = res_data.get("error") or {}
                err_msg = err_obj.get("message") or "فشل الإرسال عبر Meta Graph API"
                return jsonify({
                    "ok": False,
                    "status": "failed",
                    "graph_status": res.status_code,
                    "error_code": err_obj.get("code"),
                    "error_subcode": err_obj.get("error_subcode"),
                    "error": f"فشل الإرسال عبر Meta (كود {res.status_code}): {err_msg}"
                }), 400
            
            log_event("comment_public", f"Comment_{comment_id[:6]}", "رد علني تحت المنشور", text)
            new_msg = {
                "id": f"msg_sent_{int(time.time()*1000)}",
                "text": text,
                "message": text,
                "is_page": True,
                "sender_name": "Domya Moderator",
                "created_time": datetime.now().strftime("%I:%M %p"),
                "created_at": datetime.now(timezone.utc).isoformat(),
                "source": "human"
            }
            if isinstance(convo, dict):
                if "messages" not in convo or not isinstance(convo["messages"], list):
                    convo["messages"] = []
                convo["messages"].append(new_msg)
                convo["last_msg"] = text
                convo["snippet"] = text

            return jsonify({"ok": True, "status": "sent", "mode": "public", "graph_status": res.status_code, "id": res_data.get("id"), "message": new_msg})

        elif is_comment and reply_mode == "private":
            # Private DM reply to comment sender
            url = f"{GRAPH_URL}/me/messages"
            payload = {"recipient": {"comment_id": comment_id}, "message": {"text": text}}
            res = requests.post(url, params={"access_token": token}, json=payload, timeout=15)
            res_data = {}
            try:
                res_data = res.json()
            except Exception:
                pass

            if res.status_code >= 400 or "error" in res_data:
                err_obj = res_data.get("error") or {}
                err_msg = err_obj.get("message") or "فشل الإرسال عبر Meta Graph API"
                return jsonify({
                    "ok": False,
                    "status": "failed",
                    "graph_status": res.status_code,
                    "error_code": err_obj.get("code"),
                    "error_subcode": err_obj.get("error_subcode"),
                    "error": f"فشل الإرسال عبر Meta (كود {res.status_code}): {err_msg}"
                }), 400

            log_event("comment_private", f"Comment_{comment_id[:6]}", "رد خاص (DM)", text)
            return jsonify({"ok": True, "status": "sent", "mode": "private", "graph_status": res.status_code, "id": res_data.get("id")})

        else:
            # Standard DM reply
            recipient_id = thread_id
            if isinstance(convo, dict) and convo.get("cust_id"):
                recipient_id = str(convo.get("cust_id"))
            ok_send, detail = send_dm_reply(recipient_id, text, access_token=token)
            if not ok_send:
                return jsonify({"ok": False, "status": "failed",
                                "error": f"فشل إرسال الرسالة عبر Meta: {detail}"}), 400
            log_event("dm", f"User_{recipient_id[:6]}", "رد مباشر", text)

            # Persist sent message in conversation memory so it appears in thread history
            new_msg = {
                "id": f"msg_sent_{int(time.time()*1000)}",
                "text": text,
                "message": text,
                "is_page": True,
                "sender_name": "Domya Moderator",
                "created_time": datetime.now().strftime("%I:%M %p"),
                "created_at": datetime.now(timezone.utc).isoformat(),
                "source": "human"
            }
            if isinstance(convo, dict):
                if "messages" not in convo or not isinstance(convo["messages"], list):
                    convo["messages"] = []
                convo["messages"].append(new_msg)
                convo["last_msg"] = text
                convo["snippet"] = text

            return jsonify({"ok": True, "status": "sent", "mode": "dm", "message": new_msg})

    except Exception as e:
        print(f"[Send Reply Error] {e}")
        return jsonify({"ok": False, "error": f"خطأ بالخادم: {str(e)}"}), 500


