@app.route("/api/simulate", methods=["POST"])
def api_simulate():
    data = request.get_json() or {}
    msg = data.get("message", "")
    if not msg or not str(msg).strip():
        return jsonify({"reply": "أهلاً بك! كيف يمكننا مساعدتك؟", "source": "fallback"})
    rule = check_custom_rules(msg)
    if rule:
        reply = rule.get("response", "")
        priv = rule.get("private_response", "")
        if priv:
            reply = f"{reply} (رسالة إنبوكس: {priv})"
        return jsonify({"reply": reply, "source": "rule", "rule_triggered": rule.get("trigger")})
    rag_context = search_kb(msg)
    if GROQ_API_KEY:
        reply = _call_groq(msg, rag_context, "simulate")
        if reply:
            return jsonify({"reply": reply, "source": "llm_groq"})
    if OPENROUTER_API_KEY:
        reply = _call_openrouter(msg, rag_context, "simulate")
        if reply:
            return jsonify({"reply": reply, "source": "llm_openrouter"})
    if rag_context:
        lines = rag_context.strip().split("\n")
        first = lines[0]
        answer = first.split(": ", 1)[1] if ": " in first else rag_context
        return jsonify({"reply": f"أهلاً بيك! {answer}", "source": "rag"})
    return jsonify({"reply": "أهلاً بيك في وكالة دوميا! ابعتلنا رسالة في الخاص وهنرد عليك فوراً!", "source": "fallback"})

@app.route("/webhook", methods=["GET"])
def webhook_verify():
    mode = request.args.get("hub.mode")
    token = request.args.get("hub.verify_token")
    challenge = request.args.get("hub.challenge")
    verify_token_env = os.environ.get("VERIFY_TOKEN", "")
    if mode == "subscribe" and challenge:
        # لو VERIFY_TOKEN متظبط: لازم يطابق (آمن). لو مش متظبط: نسمح مؤقتاً لأول إعداد فقط.
        if verify_token_env:
            if token == verify_token_env:
                return str(challenge), 200
            return "Forbidden", 403
        return str(challenge), 200
    return "Forbidden", 403

@app.route("/webhook", methods=["POST"])
def webhook_event():
    cid = current_client_id()
    if cid in conv_cache: conv_cache[cid]["timestamp"] = 0
    sync_from_supabase()
    if not cache.get("bot_enabled", True):
        print("[Bot Disabled] Auto-responder is paused by user toggle")
        return "BOT_PAUSED", 200

    approval_mode = cache.get("approval_mode", "auto")

    sig_header = request.headers.get("X-Hub-Signature-256")
    if APP_SECRET and sig_header:
        if not verify_signature(request.get_data(), sig_header):
            print("[Webhook Warning] Signature mismatch, processing event permissively")

    data = request.get_json(silent=True)
    if not isinstance(data, dict) or "entry" not in data:
        return "EVENT_RECEIVED", 200

    entries = data.get("entry")
    if not isinstance(entries, list):
        return "EVENT_RECEIVED", 200

    for entry in entries:
        if not isinstance(entry, dict):
            continue
            
        target_page_id = str(entry.get("id", ""))
        webhook_token = PAGE_ACCESS_TOKEN
        matched_acct = None
        for a in ACCOUNTS_STORE:
            if str(a.get("id")) == target_page_id or str(a.get("ig_id")) == target_page_id:
                matched_acct = a
                if a.get("access_token_enc"):
                    t = decrypt(a["access_token_enc"])
                    if t and len(t) > 20:
                        webhook_token = t
                        break
                elif a.get("access_token"):
                    webhook_token = a["access_token"]
                    break

        # Auto-exchange: convert System User Token to Page Token for replying
        if webhook_token == PAGE_ACCESS_TOKEN and PAGE_ACCESS_TOKEN:
            try:
                _accts = requests.get(
                    f"{GRAPH_URL}/me/accounts?fields=id,access_token&limit=5&access_token={PAGE_ACCESS_TOKEN}",
                    timeout=8
                ).json().get("data", [])
                for _pg in _accts:
                    if _pg.get("id") == target_page_id:
                        webhook_token = _pg.get("access_token", webhook_token)
                        break
                else:
                    if _accts:
                        webhook_token = _accts[0].get("access_token", webhook_token)
            except Exception as _ex:
                print(f"[Webhook Token Exchange Error] {_ex}")

        # The per-CLIENT reply mode (set from the "وضع الرد" panel) is authoritative.
        # If the client is on manual, NOTHING is auto-sent — it goes to review instead.
        # (The old per-account dm_mode/comment_mode defaults are ignored, since every
        # account was created with "auto" baked in and would override the manual setting.)
        # Fail-safe: if we can't identify the client that owns this page, default to
        # manual (never auto-blast). Turning a client OFF (manual) always stops sending.
        _acct_cid = (matched_acct or {}).get("client_id")
        client_mode = get_client_mode(_acct_cid) if _acct_cid else "manual"
        dm_mode = client_mode
        comment_mode = client_mode
                    
        if "messaging" in entry and isinstance(entry["messaging"], list):
            for msg_event in entry["messaging"]:
                if not isinstance(msg_event, dict):
                    continue
                sender_id = msg_event.get("sender", {}).get("id")
                message = msg_event.get("message", {})
                postback = msg_event.get("postback", {})
                if not isinstance(message, dict):
                    message = {}
                if message.get("is_echo"):
                    continue
                text = message.get("text") or postback.get("payload") or postback.get("title")
                if sender_id and text:
                    stats["dms"] += 1
                    stats["ai_calls"] += 1
                    reply = generate_reply(text, platform="DM", client_id=_acct_cid)

                    if dm_mode == "manual":
                        draft_entry = {
                            "id": int(time.time()*1000),
                            "client_id": _acct_cid,
                            "type": "dm",
                            "platform": "facebook",
                            "sender": sender_id,
                            "target_id": sender_id,
                            "message": text,
                            "reply": reply,
                            "private_reply": None,
                            "status": "pending",
                            "time": datetime.now().strftime("%H:%M:%S")
                        }
                        pending_approvals.append(draft_entry)
                        push_setting("meta_ai_pending", pending_approvals)
                        stats["pending"] = len([p for p in pending_approvals if p["status"] == "pending"])
                    elif reply:
                        ok, detail = send_dm_reply(sender_id, reply, access_token=webhook_token)
                        print(f"[Auto-Send DM] client={_acct_cid} ok={ok} {str(detail)[:120]}")
                        log_event("dm", sender_id, text, reply, client_id=_acct_cid)

        if "changes" in entry and isinstance(entry["changes"], list):
            for change in entry["changes"]:
                if not isinstance(change, dict):
                    continue
                val = change.get("value", {})
                if not isinstance(val, dict):
                    continue
                field = change.get("field", "")
                
                # Check for Instagram DM in changes (field == "messages")
                if field == "messages" or "message" in val:
                    msg_obj = val.get("message", val)
                    sender_id = val.get("sender", {}).get("id") or val.get("from", {}).get("id") or val.get("sender_id")
                    text = msg_obj.get("text") if isinstance(msg_obj, dict) else None
                    if sender_id and text:
                        stats["dms"] += 1
                        stats["ai_calls"] += 1
                        reply = generate_reply(text, platform="DM", client_id=_acct_cid)
                        if dm_mode == "manual":
                            draft_entry = {
                                "id": int(time.time()*1000),
                            "client_id": _acct_cid,
                                "type": "dm",
                                "platform": "instagram",
                                "sender": sender_id,
                                "target_id": sender_id,
                                "message": text,
                                "reply": reply,
                                "private_reply": None,
                                "status": "pending",
                                "time": datetime.now().strftime("%H:%M:%S")
                            }
                            pending_approvals.append(draft_entry)
                            push_setting("meta_ai_pending", pending_approvals)
                            stats["pending"] = len([p for p in pending_approvals if p["status"] == "pending"])
                        elif reply:
                            ok, detail = send_dm_reply(sender_id, reply, access_token=webhook_token)
                            print(f"[Auto-Send IG-DM] client={_acct_cid} ok={ok} {str(detail)[:120]}")
                            log_event("dm", sender_id, text, reply, client_id=_acct_cid)
                        continue

                is_comment = (val.get("item") == "comment" and val.get("verb") == "add") or field == "comments" or (field == "feed" and val.get("item", "comment") == "comment")
                if is_comment:
                    comment_id = val.get("comment_id") or val.get("id")
                    text = val.get("message") or val.get("text")
                    sender = val.get("sender_name") or val.get("sender_id") or val.get("from", {}).get("name") or "unknown"
                    if comment_id and text:
                        stats["comments"] += 1
                        stats["ai_calls"] += 1
                        rule = check_custom_rules(text)
                        if rule:
                            pub_reply = rule.get("response") or "تم الرد في الخاص! "
                            priv_reply = rule.get("private_response")
                        else:
                            pub_reply = generate_reply(text, platform="comment", client_id=_acct_cid)
                            priv_reply = pub_reply

                        if comment_mode == "manual":
                            draft_entry = {
                                "id": int(time.time()*1000),
                            "client_id": _acct_cid,
                                "type": "comment",
                                "sender": sender,
                                "target_id": comment_id,
                                "message": text,
                                "reply": pub_reply,
                                "private_reply": priv_reply,
                                "status": "pending",
                                "time": datetime.now().strftime("%H:%M:%S")
                            }
                            pending_approvals.append(draft_entry)
                            push_setting("meta_ai_pending", pending_approvals)
                            stats["pending"] = len([p for p in pending_approvals if p["status"] == "pending"])
                        elif pub_reply:
                            send_comment_reply(comment_id, pub_reply, access_token=webhook_token)
                            if priv_reply:
                                send_private_comment_reply(comment_id, priv_reply, access_token=webhook_token)
                                log_event("comment", sender, text, pub_reply, private_reply=priv_reply, client_id=_acct_cid)
                            else:
                                log_event("comment", sender, text, pub_reply, client_id=_acct_cid)

    return "EVENT_RECEIVED", 200


# --- Multi-Account Management Routes ---
ACCOUNTS_STORE_FALLBACK = []
ACCOUNTS_STORE = cache.get("accounts") or []

def heal_orphan_accounts():
    """DISABLED per user request: do NOT auto-create clients/workspaces or auto-link
    anything the user didn't add themselves. Clients are created only via explicit
    add or the Facebook OAuth page picker."""
    return False

    global AGENCY_CLIENTS_STORE, ACCOUNTS_STORE
    valid_ids = {c.get("id") for c in AGENCY_CLIENTS_STORE}
    groups = {}
    for a in ACCOUNTS_STORE:
        # only real, connected accounts (have a token)
        if not (a.get("access_token") or a.get("access_token_enc")):
            continue
        if a.get("client_id") in valid_ids:
            continue
        key = a.get("client_id") or ("client_" + str(a.get("parent_page_id") or a.get("id")))
        groups.setdefault(key, []).append(a)
    if not groups:
        return False
    for gcid, accs in groups.items():
        fb = next((a for a in accs if a.get("platform") == "facebook"), accs[0])
        name = (fb.get("name") or "عميل جديد").replace(" (Facebook Page)", "").replace(" (Instagram)", "")
        new_client = {"id": gcid, "name": name, "company": name, "package": "Business VIP",
                      "status": "active", "is_active": True,
                      "fb_connected": any(a.get("platform") == "facebook" for a in accs),
                      "ig_connected": any(a.get("platform") == "instagram" for a in accs)}
        for a in accs:
            a["client_id"] = gcid
            if a.get("platform") == "facebook":
                new_client["page_id"] = str(a.get("id"))
            elif a.get("platform") == "instagram":
                new_client["ig_id"] = str(a.get("id"))
        AGENCY_CLIENTS_STORE.append(new_client)
    push_setting("meta_ai_clients", AGENCY_CLIENTS_STORE)
    push_setting("meta_ai_accounts", ACCOUNTS_STORE)
    cache["clients"] = AGENCY_CLIENTS_STORE
    cache["accounts"] = ACCOUNTS_STORE
    return True

