# ---- Role-based access helpers ----
def current_username():
    return session.get("uid") if has_request_context() else None

def current_user_rec():
    if has_request_context() and isinstance(session.get("user_rec"), dict) and session.get("user_rec"):
        return session.get("user_rec")
    u = current_username()
    if not u:
        return {}
    rec = USERS_DB.get(u)
    if rec and isinstance(rec, dict):
        return rec
    # Fallback lookup by employee_id or case-insensitive key
    u_str = str(u).strip().lower()
    for k, v in USERS_DB.items():
        if isinstance(v, dict):
            if str(k).strip().lower() == u_str or str(v.get("employee_id") or "").strip().lower() == u_str:
                return v
    return {}

def current_role():
    # Database user record is AUTHORITATIVE over stale session cookie
    u_rec = current_user_rec()
    if u_rec and u_rec.get("role"):
        db_role = u_rec.get("role")
        if has_request_context() and session.get("role") != db_role:
            session["role"] = db_role
            session.modified = True
        return db_role
    if has_request_context() and session.get("role"):
        return session.get("role")
    return "employee"

def is_admin():
    r = current_role()
    if r == "admin":
        return True
    u = current_username()
    if u in ("admin", "mhmd-saeed", "EMP-8086-4520"):
        return True
    rec = current_user_rec()
    if isinstance(rec, dict) and (rec.get("role") == "admin" or rec.get("is_admin")):
        return True
    return False

def is_manager():
    # admin or account_manager (i.e. not a plain employee) — can manage/assign.
    return current_role() in ("admin", "account_manager")

def is_employee():
    return current_role() == "employee"

def is_content_creator():
    role = str(current_role() or "").lower()
    if role in ("content_creator", "content", "copywriter", "writer"):
        return True
    u_rec = current_user_rec()
    job = str(u_rec.get("job") or u_rec.get("role") or "").lower()
    if any(w in job for w in ("content", "writer", "كاتب", "محتوى")):
        return True
    my_eid = _my_employee_id()
    if my_eid:
        try:
            cfg = hr_config()
            for e in _gsheet_rows(cfg["sheet_id"], cfg["employees_gid"]):
                if str(e.get("employee_id") or "").strip() == my_eid:
                    ejob = str(e.get("job") or e.get("role") or "").lower()
                    if any(w in ejob for w in ("content", "writer", "كاتب", "محتوى")):
                        return True
        except Exception as _e:
            print(f"[is_content_creator check] {_e}")
    return False

def assigned_client_ids():
    """Client ids the current user is allowed to see.
    - Admins: see ALL clients.
    - Content Creators: see ALL clients for content writing.
    - Account Managers: see ONLY their assigned clients (clients where am_employee_id/am_id matches their ID or name, or where they created/uploaded tasks).
    - Plain Employees: see ONLY their assigned clients.
    """
    if is_admin() or is_content_creator():
        return [str(c.get("id") or c.get("client_id")) for c in AGENCY_CLIENTS_STORE if (c.get("id") or c.get("client_id"))]
    
    user_rec = current_user_rec() or {}
    assigned = [str(x) for x in (user_rec.get("assigned_clients") or [])]
    my_eid = _my_employee_id()
    my_name = (user_rec.get("name") or current_username() or "").strip().lower()
    
    for c in AGENCY_CLIENTS_STORE:
        cid = str(c.get("id") or c.get("client_id") or "")
        if not cid or cid in assigned:
            continue
        c_am_id = str(c.get("am_id") or c.get("account_manager_id") or c.get("am_employee_id") or "").strip()
        c_am_name = str(c.get("am_name") or c.get("account_manager") or "").strip().lower()
        if (my_eid and c_am_id and (c_am_id == my_eid or my_eid in c_am_id)) or \
           (my_name and c_am_name and (c_am_name == my_name or my_name in c_am_name or c_am_name in my_name)):
            assigned.append(cid)
            
    # Also check task database for any clients where this Account Manager is tagged
    if is_manager() or my_eid:
        for t in _all_tasks_db():
            if not isinstance(t, dict):
                continue
            t_cid = str(t.get("client_id") or "")
            if not t_cid or t_cid in assigned:
                continue
            t_amid = str(t.get("am_id") or "").strip()
            t_amname = str(t.get("am_name") or "").strip().lower()
            if (my_eid and t_amid and (t_amid == my_eid or my_eid in t_amid)) or \
               (my_name and t_amname and (t_amname == my_name or my_name in t_amname or t_amname in my_name)):
                assigned.append(t_cid)
                
    return assigned

def can_see_client(cid):
    if is_admin() or is_content_creator():
        return True
    return str(cid) in assigned_client_ids()

def _hx(s):
    """HTML-escape a value for safe interpolation into server-rendered HTML."""
    import html as _html
    return _html.escape(str(s if s is not None else ""), quote=True)

def _is_real_client(cid):
    return any(str(c.get("id")) == str(cid) for c in AGENCY_CLIENTS_STORE)

def require_admin(f):
    @wraps(f)
    def _w(*a, **k):
        if not is_admin():
            return jsonify({"error": "صلاحيات المدير مطلوبة"}), 403
        return f(*a, **k)
    return _w

def require_manager(f):
    """Admin or Account Manager only (blocks plain employees)."""
    @wraps(f)
    def _w(*a, **k):
        if not is_manager():
            return jsonify({"error": "صلاحيات المدير أو مدير الحسابات مطلوبة"}), 403
        return f(*a, **k)
    return _w

ALLOWED_TAB_IDS = {
    "inbox", "dash", "rules", "kb", "crm", "mode", "settings", "logs",
    "scheduler", "tasks", "plan", "hr", "accounts", "analytics", "myportal", "permissions"
}

def user_effective_tabs(user_rec=None, role=None):
    """Compute the authoritative allowed tabs set for the current user."""
    if user_rec is None:
        user_rec = current_user_rec()
    if role is None:
        role = current_role()
    if role == "admin" or is_admin():
        return set(ALLOWED_TAB_IDS)
    
    custom = user_rec.get("allowed_tabs") if isinstance(user_rec, dict) else None
    if custom and isinstance(custom, list) and len(custom) > 0:
        tabs = set(custom)
        tabs.add("myportal")
        return tabs

    if role == "account_manager":
        return {"dash", "crm", "inbox", "rules", "kb", "mode", "settings", "logs", "scheduler", "tasks", "plan", "accounts", "analytics", "myportal"}
    if role in ("content_creator", "content", "copywriter", "writer") or is_content_creator():
        return {"myportal", "tasks", "plan"}
    return {"myportal"}

