def _user_session_token(username, role):
    secret = os.environ.get("SECRET_KEY") or "meta_ai_moderator_session_key_2026_super_secure"
    payload = f"{username}:{role}:{secret}"
    sig = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:24]
    return f"{username}:{role}:{sig}"

def _verify_session_token(token_str):
    if not token_str or ":" not in str(token_str):
        return None
    try:
        parts = str(token_str).split(":")
        if len(parts) != 3:
            return None
        u, r, sig = parts
        expected = _user_session_token(u, r).split(":")[-1]
        if hmac.compare_digest(sig, expected):
            return {"username": u, "role": r}
    except Exception:
        pass
    return None

@app.before_request
def global_api_guard():
    p = request.path
    if not p.startswith('/api/'):
        return
    # near-real-time scheduled publishing, driven by organic traffic (throttled 60s)
    _maybe_process_due()
    if p in PUBLIC_PATHS:
        return
    if request.method == 'OPTIONS':
        return
    
    # Check Bearer or API Key auth header for secure endpoints or API access
    auth_header = request.headers.get("Authorization", "")
    api_key_header = request.headers.get("X-API-Key", "")
    expected_secret = os.environ.get("ADMIN_API_KEY") or os.environ.get("APP_SECRET") or os.environ.get("SECRET_KEY")
    if expected_secret:
        if auth_header.startswith("Bearer "):
            token = auth_header[7:].strip()
            if hmac.compare_digest(token, expected_secret):
                return
        if api_key_header and hmac.compare_digest(api_key_header, expected_secret):
            return

    # Check persistent token in Authorization header or Cookie if session['uid'] is missing
    if 'uid' not in session:
        token_candidate = None
        if auth_header.startswith("Bearer "):
            token_candidate = auth_header[7:].strip()
        if not token_candidate:
            token_candidate = request.cookies.get("domya_token") or request.headers.get("X-Domya-Token")
        if token_candidate:
            u_info = _verify_session_token(token_candidate)
            if u_info:
                session.permanent = True
                session["uid"] = u_info["username"]
                session["role"] = u_info.get("role", "employee")
                session.modified = True

    if 'uid' not in session:
        return jsonify({"error": "Unauthorized"}), 401

    # Per-user role and tab enforcement (Strict RBAC):
    try:
        if not is_admin():
            # Exempt employee self-endpoints (their own tasks, attendance, profile info)
            is_self_endpoint = (
                p.startswith("/api/my/") or
                p.startswith("/api/me") or
                p == "/api/me" or
                "/upload-session" in p or
                "/upload-complete" in p or
                "/upload-asset" in p or
                "/content" in p or
                "/timer" in p
            )
            if not is_self_endpoint:
                eff_tabs = user_effective_tabs()
                for prefix, tab in _TAB_API_GUARD.items():
                    if p.startswith(prefix) and tab not in eff_tabs:
                        return jsonify({"error": "التبويب أو العملية غير مصرح بها لصلاحياتك", "tab_required": tab}), 403
    except Exception as _e:
        print(f"[rbac guard err] {_e}")

