@app.route("/api/meta/diagnose", methods=["GET"])
def api_meta_diagnose():
    """تشخيص التوكن: بيقول التوكن شايف إيه (صفحات/IG/صلاحيات) بدون كشف السر."""
    tok = PAGE_ACCESS_TOKEN
    out = {"has_token": bool(tok), "token_len": len(tok) if tok else 0, "pages": [], "errors": []}

    # --- Supabase persistence self-test (write + read back) ---
    supa = {"url_set": bool(SUPABASE_URL), "key_set": bool(SUPABASE_KEY), "key_len": len(SUPABASE_KEY) if SUPABASE_KEY else 0}
    if SUPABASE_URL and SUPABASE_KEY:
        try:
            testval = f"ok-{int(time.time())}"
            w = requests.post(f"{SUPABASE_URL}/rest/v1/app_settings",
                              headers=supa_headers(), json={"key": "_diag_test", "value": testval}, timeout=8)
            supa["write_status"] = w.status_code
            if w.status_code >= 400:
                supa["write_error"] = w.text[:200]
            r = requests.get(f"{SUPABASE_URL}/rest/v1/app_settings?select=value&key=eq._diag_test",
                             headers=supa_headers(), timeout=8)
            supa["read_status"] = r.status_code
            if r.status_code == 200:
                rows = r.json()
                supa["read_back"] = (rows[0].get("value") == testval) if rows else "no_rows"
            else:
                supa["read_error"] = r.text[:200]
        except Exception as e:
            supa["exception"] = str(e)[:200]
    out["supabase"] = supa
    if not tok:
        out["errors"].append("PAGE_ACCESS_TOKEN غير متظبط في الـ env")
        return jsonify(out), 200
    try:
        me = requests.get(f"{GRAPH_URL}/me?fields=id,name", params={"access_token": tok}, timeout=10)
        out["me"] = me.json() if me.status_code == 200 else {"status": me.status_code, "error": me.text[:200]}
    except Exception as e:
        out["errors"].append(f"me: {e}")
    try:
        perms = requests.get(f"{GRAPH_URL}/me/permissions", params={"access_token": tok}, timeout=10)
        if perms.status_code == 200:
            out["granted_permissions"] = [p["permission"] for p in perms.json().get("data", []) if p.get("status") == "granted"]
    except Exception as e:
        out["errors"].append(f"permissions: {e}")
    try:
        acc = requests.get(
            f"{GRAPH_URL}/me/accounts?fields=id,name,access_token,instagram_business_account{{id,username}}&limit=25",
            params={"access_token": tok}, timeout=12)
        if acc.status_code == 200:
            for pg in acc.json().get("data", []):
                out["pages"].append({
                    "id": pg.get("id"),
                    "name": pg.get("name"),
                    "has_page_token": bool(pg.get("access_token")),
                    "instagram": pg.get("instagram_business_account", {}).get("username") or None,
                    "ig_id": pg.get("instagram_business_account", {}).get("id") or None
                })
        else:
            out["errors"].append(f"/me/accounts → {acc.status_code}: {acc.text[:200]}")
    except Exception as e:
        out["errors"].append(f"accounts: {e}")
    out["page_count"] = len(out["pages"])

    # Probe each data source with the resolved page token
    if out["pages"]:
        pg = out["pages"][0]
        pid = pg["id"]; igid = pg.get("ig_id")
        # get the page token
        ptok = tok
        try:
            pt = requests.get(f"{GRAPH_URL}/{pid}?fields=access_token", params={"access_token": tok}, timeout=10)
            if pt.status_code == 200 and pt.json().get("access_token"):
                ptok = pt.json()["access_token"]
        except Exception:
            pass
        probe = {}
        def _count(label, url):
            try:
                r = requests.get(url, timeout=12)
                if r.status_code == 200:
                    probe[label] = len(r.json().get("data", []))
                else:
                    probe[label] = f"ERR {r.status_code}: {r.text[:150]}"
            except Exception as e:
                probe[label] = f"EXC {e}"
        _count("fb_messenger", f"{GRAPH_URL}/{pid}/conversations?platform=messenger&fields=id,snippet&limit=25&access_token={ptok}")
        # SAFE send-capability probe: attempt a FB Messenger send to a bogus recipient.
        # Nobody receives anything. We only read Meta's error to tell apart:
        # (#3) capability -> sending blocked (needs App Review / Live)
        # #100 invalid recipient / user-not-found -> sending WORKS, just needs a real PSID
        try:
            sp = requests.post(f"{GRAPH_URL}/me/messages", params={"access_token": ptok},
                               json={"recipient": {"id": "000000000000000"}, "messaging_type": "RESPONSE",
                                     "message": {"text": "capability probe"}}, timeout=10)
            _err = (sp.json().get("error") or {}) if sp.headers.get("content-type","").startswith("application/json") else {}
            probe["fb_dm_send_probe"] = {
                "status": sp.status_code,
                "code": _err.get("code"),
                "subcode": _err.get("error_subcode"),
                "msg": (_err.get("message") or sp.text)[:160],
                "verdict": ("BLOCKED_#3_needs_live" if _err.get("code") == 3
                            else "SEND_OK_needs_real_recipient" if _err.get("code") in (100, 551, 10) or sp.status_code == 200
                            else "unknown")
            }
        except Exception as e:
            probe["fb_dm_send_probe"] = f"EXC {e}"
        # IG DM — try both page-scoped and IG-user-scoped endpoints
        try:
            r = requests.get(f"{GRAPH_URL}/{pid}/conversations?platform=instagram&fields=id&limit=10&access_token={ptok}", timeout=10)
            probe["ig_dm_via_page"] = len(r.json().get("data", [])) if r.status_code == 200 else f"ERR {r.status_code}: {r.text[:180]}"
        except Exception as e:
            probe["ig_dm_via_page"] = f"TIMEOUT {e}"
        if igid:
            try:
                r = requests.get(f"{GRAPH_URL}/{igid}/conversations?fields=id&limit=10&access_token={ptok}", timeout=10)
                probe["ig_dm_via_iguser"] = len(r.json().get("data", [])) if r.status_code == 200 else f"ERR {r.status_code}: {r.text[:180]}"
            except Exception as e:
                probe["ig_dm_via_iguser"] = f"TIMEOUT {e}"
        # Count ACTUAL comments on FB posts
        try:
            r = requests.get(f"{GRAPH_URL}/{pid}/feed?fields=id,comments.limit(50){{id,message}}&limit=25&access_token={ptok}", timeout=20)
            if r.status_code == 200:
                posts = r.json().get("data", [])
                probe["fb_posts"] = len(posts)
                probe["fb_comments_total"] = sum(len(p.get("comments", {}).get("data", [])) for p in posts)
            else:
                probe["fb_posts"] = f"ERR {r.status_code}: {r.text[:150]}"
        except Exception as e:
            probe["fb_posts"] = f"EXC {e}"
        if igid:
            try:
                r = requests.get(f"{GRAPH_URL}/{igid}/media?fields=id,comments_count,comments.limit(50){{id,text}}&limit=25&access_token={ptok}", timeout=20)
                if r.status_code == 200:
                    media = r.json().get("data", [])
                    probe["ig_media"] = len(media)
                    probe["ig_comments_total"] = sum(m.get("comments_count", 0) for m in media)
                else:
                    probe["ig_media"] = f"ERR {r.status_code}: {r.text[:150]}"
            except Exception as e:
                probe["ig_media"] = f"EXC {e}"
        out["probe"] = probe

    out["verdict"] = ("جاهز — الصفحات ظاهرة، السحب المفروض يشتغل" if out["pages"]
                      else "التوكن شغّال بس مفيش صفحات ظاهرة — راجع صلاحيات/تعيين الصفحة للـ System User")
    return jsonify(out), 200

@app.route("/api/system/diagnostics", methods=["GET"])
@require_admin
def api_system_diagnostics():
    """Comprehensive real-time system health & connectivity report for Admin."""
    report = {
        "status": "ok",
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "environment": {
            "admin_pass_set": bool(os.environ.get("ADMIN_PASS")),
            "secret_key_set": bool(os.environ.get("SECRET_KEY")),
            "supabase_url_set": bool(SUPABASE_URL),
            "supabase_key_set": bool(SUPABASE_KEY),
            "groq_api_key_set": bool(os.environ.get("GROQ_API_KEY")),
            "openrouter_key_set": bool(os.environ.get("OPENROUTER_API_KEY")),
            "telegram_token_set": bool(os.environ.get("TELEGRAM_BOT_TOKEN") or os.environ.get("TELEGRAM_TASKS_BOT_TOKEN")),
            "hr_sheet_id_set": bool(os.environ.get("HR_SHEET_ID"))
        },
        "services": {}
    }
    
    # 1. Supabase Health Check
    if SUPABASE_URL and SUPABASE_KEY:
        try:
            r = requests.get(f"{SUPABASE_URL}/rest/v1/settings?select=key&limit=1", headers=supa_headers(), timeout=5)
            report["services"]["supabase"] = {
                "ok": r.status_code == 200,
                "status_code": r.status_code,
                "latency_ms": int(r.elapsed.total_seconds() * 1000) if hasattr(r, 'elapsed') else 0,
                "error": None if r.status_code == 200 else r.text[:150]
            }
        except Exception as e:
            report["services"]["supabase"] = {"ok": False, "error": str(e)[:150]}
    else:
        report["services"]["supabase"] = {"ok": False, "error": "SUPABASE_URL or SUPABASE_KEY not configured"}

    # 2. LLM Provider (Groq) Check
    groq_key = os.environ.get("GROQ_API_KEY")
    if groq_key:
        try:
            r = requests.get("https://api.groq.com/openai/v1/models", headers={"Authorization": f"Bearer {groq_key}"}, timeout=5)
            report["services"]["groq_llm"] = {
                "ok": r.status_code == 200,
                "status_code": r.status_code,
                "error": None if r.status_code == 200 else r.text[:150]
            }
        except Exception as e:
            report["services"]["groq_llm"] = {"ok": False, "error": str(e)[:150]}
    else:
        report["services"]["groq_llm"] = {"ok": False, "error": "GROQ_API_KEY not configured"}

    # 3. Telegram Bot Check
    tg_token = os.environ.get("TELEGRAM_BOT_TOKEN") or os.environ.get("TELEGRAM_TASKS_BOT_TOKEN")
    if tg_token:
        try:
            r = requests.get(f"https://api.telegram.org/bot{tg_token}/getMe", timeout=5)
            if r.status_code == 200:
                bdata = r.json().get("result", {})
                report["services"]["telegram"] = {"ok": True, "bot_username": bdata.get("username"), "bot_name": bdata.get("first_name")}
            else:
                report["services"]["telegram"] = {"ok": False, "status_code": r.status_code, "error": r.text[:150]}
        except Exception as e:
            report["services"]["telegram"] = {"ok": False, "error": str(e)[:150]}
    else:
        report["services"]["telegram"] = {"ok": False, "error": "TELEGRAM_BOT_TOKEN not configured"}

    # 4. Meta Graph API Check
    tok = PAGE_ACCESS_TOKEN
    if tok:
        try:
            r = requests.get(f"{GRAPH_URL}/me?fields=id,name", params={"access_token": tok}, timeout=5)
            report["services"]["meta_graph"] = {
                "ok": r.status_code == 200,
                "name": r.json().get("name") if r.status_code == 200 else None,
                "error": None if r.status_code == 200 else r.text[:150]
            }
        except Exception as e:
            report["services"]["meta_graph"] = {"ok": False, "error": str(e)[:150]}
    else:
        report["services"]["meta_graph"] = {"ok": False, "error": "PAGE_ACCESS_TOKEN not configured"}

    # Overall system health
    all_ok = all(s.get("ok", False) for s in report["services"].values())
    report["overall_health"] = "healthy" if all_ok else "warning"

    return jsonify(report), 200

