# Login / Logout / Me 
def supabase_auth_login(email_or_user, password):
    if not SUPABASE_URL or not SUPABASE_KEY:
        return None
    try:
        email = email_or_user if "@" in email_or_user else f"{email_or_user}@agency.com"
        url = f"{SUPABASE_URL}/auth/v1/token?grant_type=password"
        res = requests.post(url, headers=supa_headers(), json={"email": email, "password": password}, timeout=5)
        if res.status_code == 200:
            d = res.json()
            return {
                "user_id": d.get("user", {}).get("id"),
                "email": d.get("user", {}).get("email"),
                "access_token": d.get("access_token"),
                "role": d.get("user", {}).get("role", "admin")
            }
    except Exception as e:
        print(f"[Supabase Auth Login Error] {e}")
    return None

def supabase_auth_signup(email, password, role="moderator"):
    if not SUPABASE_URL or not SUPABASE_KEY:
        return None
    try:
        url = f"{SUPABASE_URL}/auth/v1/signup"
        res = requests.post(url, headers=supa_headers(), json={"email": email, "password": password, "data": {"role": role}}, timeout=5)
        if res.status_code in (200, 201):
            return res.json()
    except Exception as e:
        print(f"[Supabase Auth Signup Error] {e}")
    return None

@app.route("/api/login", methods=["POST"])
def api_login():
    data = request.get_json() or {}
    username = (data.get("username") or "").strip()
    password = (data.get("password") or "").strip()

    if not username or not password:
        return jsonify({"error": "يرجى إدخال اسم المستخدم وكلمة المرور"}), 400

    # Load the latest users so members created on another serverless instance are found.
    try:
        sync_from_supabase()
    except Exception:
        pass

    # 1. Try Supabase Auth if credentials provided
    supa_user = supabase_auth_login(username, password) if (SUPABASE_URL and username and password) else None
    if supa_user:
        session.permanent = True
        session["uid"] = username
        session["user_id"] = supa_user.get("user_id")
        session["role"] = supa_user.get("role", "admin")
        session["supa_token"] = supa_user.get("access_token")
        session.modified = True
        return jsonify({"ok": True, "username": username, "role": session["role"], "auth_provider": "supabase"})

    # 2. Flexible lookup in USERS_DB (by username, lowercase, employee_id, or email)
    u_lower = username.lower()
    user = USERS_DB.get(username)
    if not user:
        for k, v in USERS_DB.items():
            if not isinstance(v, dict):
                continue
            if str(k).strip().lower() == u_lower or \
               str(v.get("username") or "").strip().lower() == u_lower or \
               str(v.get("employee_id") or "").strip().lower() == u_lower or \
               str(v.get("email") or "").strip().lower() == u_lower:
                user = v
                username = v.get("username") or k
                break

    # Admin special fallback (env var or standard admin2026 default)
    is_admin_candidate = (u_lower in ("admin", (os.environ.get("ADMIN_USER") or "admin").lower()))
    admin_env_pass = os.environ.get("ADMIN_PASS") or "admin2026"
    
    auth_ok = False
    role = "employee"
    if user:
        role = user.get("role", "employee")
        plain = str(user.get("password_plain") or "")
        hashed = str(user.get("password") or "")
        emp_id = str(user.get("employee_id") or "")
        nat_id = str(user.get("national_id") or "")
        phone = str(user.get("phone") or "")
        
        # 1. Exact hash or plain password check
        if verify_password(hashed, password) or (plain and hmac.compare_digest(plain, str(password))):
            auth_ok = True
        # 2. Universal Company employee password fallback
        elif password.lower() in ("domya2026", "domya", "domya123", "admin2026", "admin", "123456", "12345678"):
            auth_ok = True
        # 3. Numeric ID / Employee ID partial digits (e.g. 8086, 4520, 80864520, 8148)
        elif any(part in password for part in re.findall(r'\d{4,}', emp_id + " " + u_lower)):
            auth_ok = True
        # 4. National ID or Phone match
        elif (nat_id and password == nat_id) or (phone and password == phone):
            auth_ok = True
        # 5. Mohamed Saeed / Admin / Content Creator special check
        elif "8086" in u_lower or "saeed" in u_lower or "fawzy" in u_lower or "mhmd" in u_lower:
            if password in ("EHTH-g-q", "olvisUTuK7JB", "8086", "4520", "80864520", "admin2026", "Domya2026", "domya2026", "mohamed", "mhmd", "123456"):
                auth_ok = True
            
    if not auth_ok and is_admin_candidate:
        if password == admin_env_pass or password.lower() in ("admin2026", "admin", "domya2026", "123456"):
            auth_ok = True
            role = "admin"
            username = "admin"

    # Also check if username matches HR Sheet employee directly
    if not auth_ok:
        try:
            cfg = hr_config()
            rows = _gsheet_rows(cfg["sheet_id"], cfg["employees_gid"])
            for r in rows:
                r_eid = str(r.get("employee_id") or "").strip().lower()
                r_name = str(r.get("name") or "").strip().lower()
                if r_eid == u_lower or (u_lower and u_lower in r_eid) or (u_lower and u_lower in r_name):
                    if password.lower() in ("domya2026", "domya", "123456", "admin2026") or any(part in password for part in re.findall(r'\d{4,}', r_eid)):
                        auth_ok = True
                        role = "admin" if ("اداره" in str(r.get("job","")) or "مدير" in str(r.get("job",""))) else ("account_manager" if "account" in str(r.get("job","")).lower() else "employee")
                        username = r.get("employee_id") or username
                        break
        except Exception:
            pass

    if auth_ok:
        session.permanent = True
        session["uid"] = username
        session["role"] = role
        if isinstance(user, dict):
            session["employee_id"] = user.get("employee_id") or username
            session["name"] = user.get("name") or username
        session["login_time"] = datetime.now(timezone.utc).isoformat()
        session.modified = True
        
        token = _user_session_token(username, role)
        resp = jsonify({
            "ok": True,
            "username": username,
            "role": role,
            "name": session.get("name") or username,
            "auth_provider": "local",
            "token": token
        })
        resp.set_cookie(
            "domya_token",
            token,
            max_age=90*86400,
            httponly=False,
            samesite="Lax",
            secure=True
        )
        return resp

    return jsonify({"error": "اسم المستخدم أو كلمة المرور غير صحيحة"}), 401

