def _supabase_get_setting(key):
    """Read one app_settings value fresh from Supabase (bypasses per-instance memory)."""
    if not (SUPABASE_URL and SUPABASE_KEY):
        return None
    try:
        r = requests.get(f"{SUPABASE_URL}/rest/v1/app_settings?select=value&key=eq.{key}",
                         headers=supa_headers(), timeout=6)
        if r.status_code == 200 and r.json():
            v = r.json()[0].get("value")
            parsed = json.loads(v) if isinstance(v, str) else v
            if isinstance(parsed, str):
                try:
                    parsed = json.loads(parsed)
                except Exception:
                    pass
            return parsed
    except Exception as e:
        print(f"[supa get {key}] {e}")
    return None

def _norm(s):
    try:
        return unicodedata.normalize("NFC", str(s)).strip()
    except Exception:
        return str(s).strip()

@app.route("/api/users/<username>", methods=["DELETE"])
@app.route("/api/users/delete", methods=["POST"])
@require_admin
def api_users_delete(username=None):
    body = request.get_json(silent=True) or {}
    uname = _norm(username or body.get("username") or request.args.get("username") or "")
    if uname == _norm(admin_user):
        return jsonify({"error": "لا يمكن حذف حساب المدير الرئيسي"}), 400
    # Operate on the authoritative Supabase copy so a stale instance can't fail the delete.
    users = _supabase_get_setting("meta_ai_users")
    if not isinstance(users, dict):
        users = dict(USERS_DB)
    match = next((k for k in users if _norm(k) == uname), None)
    if not match:
        return jsonify({"error": "المستخدم غير موجود"}), 404
    users.pop(match, None)
    USERS_DB.pop(match, None)
    push_setting("meta_ai_users", users)
    return jsonify({"ok": True, "deleted": match})


@app.route("/api/auth/send-credentials", methods=["POST"])
@require_admin
def api_send_credentials():
    """Admin-only. Passwords are hashed and cannot be read back, so this issues a NEW
    password, stores it hashed, and emails the plaintext to the member once."""
    data = request.get_json() or {}
    username = (data.get("username") or "").strip()
    user = USERS_DB.get(username)
    if not user:
        return jsonify({"error": "المستخدم غير موجود"}), 404
    target_email = (data.get("email") or user.get("email") or "").strip()
    if not target_email:
        return jsonify({"error": "لا يوجد بريد إلكتروني لهذا المستخدم"}), 400
    new_password = secrets.token_urlsafe(9)
    user["password"] = hash_password(new_password)
    user["password_plain"] = new_password
    USERS_DB[username] = user
    push_setting("meta_ai_users", USERS_DB)
    email_ok, email_msg = send_credentials_email(target_email, username, new_password, action="welcome")
    return jsonify({"ok": email_ok, "recipient": target_email, "message": email_msg})


@app.route("/api/auth/reset-password", methods=["POST"])
def api_reset_password():
    """Forgot-password: issues a new password, stores it hashed, and emails it to the
    account's own email. Never returns the password in the response."""
    data = request.get_json() or {}
    username = (data.get("username") or "").strip()
    email = (data.get("email") or "").strip()
    user = USERS_DB.get(username)
    if not user and email:
        user = next((u for u in USERS_DB.values() if isinstance(u, dict) and u.get("email") == email), None)
    if not user:
        # Do not reveal whether the account exists.
        return jsonify({"ok": True, "message": "لو الحساب موجود، هيتم إرسال كلمة مرور جديدة على بريده."})
    target_user = user.get("username")
    target_email = user.get("email") or ""
    new_password = secrets.token_urlsafe(9)
    user["password"] = hash_password(new_password)
    user["password_plain"] = new_password
    USERS_DB[target_user] = user
    push_setting("meta_ai_users", USERS_DB)
    if target_email:
        send_credentials_email(target_email, target_user, new_password, action="reset")
@app.route("/api/auth/change-password", methods=["POST"])
@auth_guard
def api_change_password():
    sync_from_supabase()
    data = request.get_json() or {}
    new_password = (data.get("new_password") or data.get("password") or "").strip()
    target_user = (data.get("username") or current_username() or "admin").strip()
    
    if not new_password:
        return jsonify({"error": "يرجى كتابة كلمة المرور الجديدة"}), 400
    if len(new_password) < 4:
        return jsonify({"error": "كلمة المرور يجب أن تكون 4 أحرف أو أرقام على الأقل"}), 400
        
    if target_user != current_username() and not is_admin():
        return jsonify({"error": "غير مصرح لك بتغيير كلمة مرور مستخدم آخر"}), 403
        
    user_rec = USERS_DB.get(target_user)
    if not user_rec:
        for k, v in USERS_DB.items():
            if isinstance(v, dict) and (str(k).lower() == target_user.lower() or str(v.get("username") or "").lower() == target_user.lower()):
                user_rec = v
                target_user = k
                break
    if not user_rec:
        user_rec = {"username": target_user, "role": "admin" if target_user == "admin" else "employee"}
        
    user_rec["password"] = hash_password(new_password)
    user_rec["password_plain"] = new_password
    if target_user.lower() == "admin":
        user_rec["role"] = "admin"
        user_rec["custom_pass"] = True
    USERS_DB[target_user] = user_rec
    push_setting("meta_ai_users", USERS_DB)
    return jsonify({"ok": True, "message": f"تم تغيير كلمة مرور {target_user} بنجاح "})


