@app.route("/api/me", methods=["GET"])
def api_me():
    if "uid" not in session:
        return jsonify({"logged_in": False}), 200
    sync_from_supabase()
    rec = current_user_rec()
    role = current_role()
    session["role"] = role
    session.modified = True
    emp_id = rec.get("employee_id") if isinstance(rec, dict) else ""
    if not emp_id and session.get("uid", "").startswith("EMP-"):
        emp_id = session.get("uid")
    emp_info = _sheet_emp(emp_id) if emp_id else {}
    emp_name = (rec.get("name") if isinstance(rec, dict) else "") or emp_info.get("name") or session.get("name") or session.get("uid") or ""
    return jsonify({
        "logged_in": True,
        "username": session.get("uid"),
        "user_id": session.get("user_id"),
        "role": role,
        "is_admin": is_admin(),
        "is_manager": is_manager(),
        "employee_id": emp_id,
        "name": emp_name,
        "allowed_tabs": list(user_effective_tabs(rec, role)),
        "assigned_clients": assigned_client_ids(),
        "active_client_id": current_client_id(),
        "supabase_connected": bool(SUPABASE_URL and SUPABASE_KEY),
        "clients_count": len(AGENCY_CLIENTS_STORE),
        "accounts_count": len(ACCOUNTS_STORE)
    })


