@app.route("/api/clients", methods=["GET"])
def api_clients_get():
    sync_from_supabase()
    heal_orphan_accounts()
    show_archived = request.args.get("archived") == "true"
    pool = AGENCY_CLIENTS_STORE if show_archived else [c for c in AGENCY_CLIENTS_STORE if c.get("is_active", True)]
    
    # Enrich every client with AM name for crystal-clear clarity for the Manager/Admin
    all_tasks = _all_tasks_db()
    for c in pool:
        if not isinstance(c, dict):
            continue
        c_amid = str(c.get("am_employee_id") or c.get("am_id") or "").strip()
        c_amname = str(c.get("am_name") or c.get("account_manager") or "").strip()
        if not c_amname:
            if c_amid in ("AM-2072-9827", "EMP-2072-9827"):
                c["am_name"] = "محمود خالد"
                c["am_employee_id"] = "AM-2072-9827"
            elif c_amid in ("EMP-5887-5256", "AM-5887-5256"):
                c["am_name"] = "آيه أحمد مجاهد"
                c["am_employee_id"] = "EMP-5887-5256"
            else:
                # Find from tasks if any task exists for this client
                cid = str(c.get("id") or "")
                c_task = next((t for t in all_tasks if str(t.get("client_id") or "") == cid and t.get("am_name")), None)
                if c_task:
                    c["am_name"] = c_task.get("am_name")
                    c["am_employee_id"] = c_task.get("am_id") or c_amid or "AM-2072-9827"
                else:
                    c["am_name"] = "محمود خالد"
                    c["am_employee_id"] = c_amid or "AM-2072-9827"

    # Filter by user role: Admins and Content Creators see all, Account Managers see only their assigned clients
    if not (is_admin() or is_content_creator()):
        allowed = set(assigned_client_ids())
        pool = [c for c in pool if str(c.get("id") or c.get("client_id")) in allowed]
        
    return jsonify(pool)

@app.route("/api/clients", methods=["POST"])
@require_manager
def api_clients_add():
    data = request.get_json() or {}
    name = data.get("name", "").strip()
    if not name:
        return jsonify({"error": "اسم العميل/البراند مطلوب"}), 400
    # Honor an explicit id (used to re-link/recover an existing client + its accounts).
    cid = str(data.get("id") or "").strip()
    if not cid:
        cid = "client_" + re.sub(r"[^a-z0-9]", "", name.lower().replace(" ", "_"))[:30]
    if not cid or len(cid) < 8:
        cid = f"client_{int(time.time())}"
        
    # Only use real page/token if EXPLICITLY provided (manual). Otherwise the client
    # starts EMPTY and pages are attached later via Facebook OAuth (the correct flow).
    # Only use a page/token if EXPLICITLY provided (manual entry). Otherwise the client
    # starts EMPTY and real pages are attached later via Facebook OAuth — never auto-attach
    # the default Domya page to every new client.
    page_id = str(data.get("page_id") or "").strip()
    ig_id = str(data.get("ig_id") or "").strip()
    token = (data.get("access_token") or "").strip()

    new_client = {
        "id": cid,
        "name": name,
        "company": data.get("company") or name,
        "package": data.get("package", "Business VIP"),
        "page_id": page_id or None,
        "ig_id": ig_id or None,
        "status": "active",
        "is_active": True,
        "fb_connected": bool(page_id and token),
        "ig_connected": bool(ig_id and token),
    }

    existing_c = next((c for c in AGENCY_CLIENTS_STORE if c["id"] == cid), None)
    if existing_c:
        existing_c.update(new_client)
    else:
        AGENCY_CLIENTS_STORE.append(new_client)

    global ACCOUNTS_STORE
    # Only register real accounts when a genuine page_id + token were provided manually.
    if page_id and token:
        fb_acc = {"id": page_id, "name": f"{name} (Facebook Page)", "platform": "facebook", "access_token": token, "client_id": cid, "status": "connected", "is_active": True, "dm_mode": "auto", "comment_mode": "auto"}
        ACCOUNTS_STORE = [a for a in ACCOUNTS_STORE if str(a.get("id")) != page_id]
        ACCOUNTS_STORE.append(fb_acc)
        if ig_id:
            ig_acc = {"id": ig_id, "name": f"{name} (Instagram)", "platform": "instagram", "ig_id": ig_id, "access_token": token, "client_id": cid, "status": "connected", "is_active": True, "dm_mode": "auto", "comment_mode": "auto"}
            ACCOUNTS_STORE = [a for a in ACCOUNTS_STORE if str(a.get("id")) != ig_id]
            ACCOUNTS_STORE.append(ig_acc)
        push_setting("meta_ai_accounts", ACCOUNTS_STORE)

    push_setting("meta_ai_clients", AGENCY_CLIENTS_STORE)
    return jsonify({"ok": True, "client": new_client, "id": cid, "needs_connect": not (page_id and token)})

