@app.route("/api/clients/<cid>", methods=["DELETE"])
@require_admin
def api_clients_delete(cid):
    # Load the full client list first so a stale serverless instance never overwrites
    sync_from_supabase()
    data = request.get_json() or {}
    confirm = str(data.get("confirm_name") or "").strip()
    
    # Match client by ID or Name
    client = next((c for c in AGENCY_CLIENTS_STORE if str(c.get("id") or "") == str(cid) or str(c.get("name") or "") == str(cid)), None)
    if not client:
        # Client is already deleted from DB — return OK 200 so UI syncs immediately
        return jsonify({"ok": True, "message": "تم حذف العميل بنجاح"})
        
    c_name = str(client.get("name") or "").strip()
    if confirm and confirm.lower() != c_name.lower():
        return jsonify({"error": "اسم التأكيد لا يطابق اسم العميل"}), 403
        
    actual_cid = str(client.get("id") or cid)
    
    # Cascade delete: remove associated KB, rules, accounts, and tasks
    global ACCOUNTS_STORE
    ACCOUNTS_STORE = [a for a in ACCOUNTS_STORE if str(a.get("client_id") or "") != actual_cid]
    kb = get_kb_data()
    kb = [item for item in kb if str(item.get("client_id") or "") != actual_cid]
    cache["kb"] = kb
    push_setting("meta_ai_kb", kb)
    rules = get_rules_data()
    rules = [r for r in rules if str(r.get("client_id") or "") != actual_cid]
    cache["rules"] = rules
    push_setting("meta_ai_rules", rules)
    
    AGENCY_CLIENTS_STORE[:] = [c for c in AGENCY_CLIENTS_STORE if str(c.get("id") or "") != actual_cid and str(c.get("name") or "") != c_name]
    push_setting("meta_ai_clients", AGENCY_CLIENTS_STORE)
    push_setting("meta_ai_accounts", ACCOUNTS_STORE)
    
    try:
        supa_delete("meta_ai_clients", f"id=eq.{actual_cid}")
    except Exception:
        pass
        
    return jsonify({"ok": True, "message": "تم حذف العميل بنجاح"})

