@app.route('/api/cron/process_scheduled', methods=['GET', 'POST'])
def process_scheduled_cron():
    # Accept Vercel Cron (Bearer CRON_SECRET) OR an external minute-level cron via ?key=
    cron_secret = os.environ.get('CRON_SECRET', '')
    if cron_secret:
        auth_header = request.headers.get('authorization', '')
        key = request.args.get('key', '') or request.args.get('secret', '')
        if auth_header != f"Bearer {cron_secret}" and key != cron_secret:
            return jsonify({"error": "Unauthorized"}), 401

    sync_from_supabase()
    published = _process_due_posts()
    reminders = 0
    try:
        reminders = _send_due_task_reminders()
    except Exception as e:
        print(f"[due reminders] {e}")
    return jsonify({
        "status": "processed",
        "pending_count": len(pending_approvals),
        "published": published,
        "task_reminders_sent": reminders
    }), 200


def _emp_chat(emp_id):
    return str((_sheet_emp(emp_id) or {}).get("telegram_id", "")).replace(".0", "").strip()

def _send_due_task_reminders(force=False):
    """DM every employee the tasks on their turn today. Fires once per day at/after
    09:00 Cairo (DST-aware), deduped across instances via a persisted date."""
    now_cairo = _cairo_now()
    today = now_cairo.date().isoformat()
    if not force:
        if str(cache.get("reminders_sent_date") or "") == today:
            return 0 # already sent today
        if now_cairo.hour < 9:
            return 0 # too early — wait until 9 AM Cairo
    cache["reminders_sent_date"] = today
    push_setting("meta_ai_reminders_date", today)
    active = {"Assigned", "In Progress", "Awaiting AM Review"}
    by_emp = {}
    for t in _all_tasks_db():
        if not isinstance(t, dict):
            continue
        eid = str(t.get("assigned_employee_id") or "").strip()
        if not eid or t.get("status") not in active:
            continue
        due = str(t.get("delivery_deadline") or t.get("publish_date") or t.get("scheduled_start_date") or "")[:10]
        if due and due <= today: # due today or overdue
            by_emp.setdefault(eid, []).append(t)
    sent = 0
    portal = globals().get("PORTAL_URL", "https://metaaimoderator.vercel.app")
    for eid, tasks in by_emp.items():
        chat = _emp_chat(eid)
        if not chat:
            continue
        name = (_sheet_emp(eid) or {}).get("name", "")
        lines = [f"️ صباح الخير {name}", f"عندك {len(tasks)} مهمة على دورك النهاردة:\n"]
        for t in tasks[:15]:
            due = str(t.get("delivery_deadline") or t.get("publish_date") or "")[:10]
            flag = " متأخرة" if (due and due < today) else " مستحقة اليوم"
            lines.append(f"{flag} • {t.get('title','مهمة')} ({t.get('status')})")
        lines.append(f"\nافتح مهامك من البورتال:\n{portal}")
        if send_telegram_bot_notification(chat, "\n".join(lines)):
            sent += 1
    return sent


