        task_obj["task_id"] = tid
        task_obj["id"] = tid
        task_obj["client_id"] = r.get("client_id") or task_obj.get("client_id") or "cli_general"
        task_obj["client_name"] = r.get("client_name") or task_obj.get("client_name") or ""
        task_obj["plan_name"] = r.get("plan_name") or task_obj.get("plan_name") or ""
        task_obj["file_name"] = task_obj.get("file_name") or task_obj["plan_name"]
        task_obj["title"] = r.get("title") or task_obj.get("title") or "مهمة"
        task_obj["status"] = r.get("status") or task_obj.get("status") or "Pending AM Approval"
        task_obj["assigned_employee_id"] = r.get("assigned_employee_id") or task_obj.get("assigned_employee_id") or ""
        task_obj["assignee_name"] = r.get("assignee_name") or task_obj.get("assignee_name") or ""
        task_obj["am_name"] = r.get("am_name") or task_obj.get("am_name") or "محمود خالد"
