def _all_tasks_db():
    """ALL tasks across every client — Supabase (authoritative, ultra-fast sub-50ms SQL)
    merged with in-memory cache and Google Sheets."""
    tasks_map = {}
    
    # 1. Authoritative: Read from Supabase mam_tasks (instant, persistent)
    try:
        if SUPABASE_URL and SUPABASE_KEY and len(SUPABASE_URL) > 15:
            rows = supa_select("mam_tasks", "select=*")
            for r in (rows or []):
                d = r.get("data")
                if isinstance(d, dict):
                    d = _sanitize_task_record(d)
                    tid = str(r.get("task_id") or d.get("task_id") or "")
                    if tid:
                        d.setdefault("client_id", r.get("client_id"))
                        tasks_map[tid] = d
    except Exception as e:
        print(f"[all tasks db supa] {e}")

    # 2. In-memory cache fallback
    for t in (cache.get("tasks") or []):
        if isinstance(t, dict):
            tid = str(t.get("task_id") or t.get("id") or "")
            if tid and tid not in tasks_map:
                tasks_map[tid] = _sanitize_task_record(t)

    # 3. Read from Google Sheets Tasks tab if tasks_map is empty
    if not tasks_map:
        try:
            sheet_tasks = _gsheet_tasks_read()
            for t in sheet_tasks:
                tid = str(t.get("task_id") or t.get("id") or "")
                if tid:
                    tasks_map[tid] = t
        except Exception as err:
            print(f"[_all_tasks_db sheet read error] {err}")

    out = list(tasks_map.values())
    out.sort(key=_natural_task_sort_key)
    cache["tasks"] = out
    return out


def get_client_tasks(_cid=None):
    _cid = _cid or current_client_id()
    all_t = _all_tasks_db()
    client_tasks = [t for t in all_t if str(t.get("client_id") or "").strip() == str(_cid).strip()]
    client_tasks.sort(key=_natural_task_sort_key)
    return client_tasks


def _generate_system_unique_task_ids(count=1):
    """Generates globally unique, strictly sequential TASK-xxxx IDs across all clients and plans in the system."""
    all_tasks = _all_tasks_db()
    max_num = 0
    for t in all_tasks:
        tid = str(t.get("task_id") or "")
        m = re.search(r'TASK-(\d+)', tid)
        if m:
            try:
                num = int(m.group(1))
                if num > max_num:
                    max_num = num
            except Exception:
                pass
    return [f"TASK-{max_num + i:04d}" for i in range(1, count + 1)]


def save_client_tasks(tasks_list, _cid=None):
    """Saves and merges tasks for client _cid into the persistent database without deleting other clients' data."""
    _cid = _cid or current_client_id()
    if not isinstance(tasks_list, list):
        return
    current_all = _all_tasks_db()
    task_map = {str(t.get("task_id") or t.get("id")): t for t in current_all if isinstance(t, dict) and (t.get("task_id") or t.get("id"))}

    for t in tasks_list:
        if isinstance(t, dict):
            tid = str(t.get("task_id") or t.get("id") or "")
            if tid:
                t["client_id"] = t.get("client_id") or _cid
                task_map[tid] = _sanitize_task_record(t)

    updated_all = list(task_map.values())
    updated_all.sort(key=_natural_task_sort_key)
    cache["tasks"] = updated_all

    # 1. Save to Supabase immediately (authoritative, ultra-fast sub-50ms)
    if SUPABASE_URL and SUPABASE_KEY and len(SUPABASE_URL) > 15:
        rows_to_upsert = []
        for t in tasks_list:
            if isinstance(t, dict):
                tid = str(t.get("task_id") or t.get("id") or "")
                if tid:
                    rows_to_upsert.append({
                        "task_id": tid,
                        "client_id": str(t.get("client_id") or _cid),
                        "status": str(t.get("status") or "Pending AM Approval"),
                        "assigned_employee_id": str(t.get("assigned_employee_id") or "") or None,
                        "data": t
                    })
        if rows_to_upsert:
            try:
                supa_upsert("mam_tasks", rows_to_upsert)
            except Exception as _se:
                print(f"[save_client_tasks supa err] {_se}")

    # 2. Sync to Google Sheets in background thread so HTTP requests never block or lag
    try:
        import threading
        t_bg = threading.Thread(target=_gsheet_tasks_save_all, args=(updated_all,), daemon=True)
        t_bg.start()
    except Exception as _ge:
        print(f"[save_client_tasks gsheet thread err] {_ge}")


