def _drive_find_folder_by_name(parent_id, name_prefix):
    """Find an existing non-trashed folder inside parent_id matching name_prefix."""
    token = get_google_oauth_access_token()
    if not token or not name_prefix:
        return None
    try:
        clean_prefix = str(name_prefix).strip()
        q = urllib.parse.quote(f"trashed = false and mimeType = 'application/vnd.google-apps.folder' and '{parent_id}' in parents and name contains '{clean_prefix}'")
        req = urllib.request.Request(
            f"https://www.googleapis.com/drive/v3/files?q={q}&fields=files(id,name)&pageSize=1",
            headers={"Authorization": f"Bearer {token}"}
        )
        res = json.loads(urllib.request.urlopen(req, timeout=10).read().decode('utf-8'))
        files = res.get("files", [])
        if files:
            return files[0].get("id")
    except Exception as e:
        print(f"[_drive_find_folder error] {e}")
    return None


def _ensure_client_record(client_input, am_id=None):
    """Guarantees that client_input (name or ID) exists in AGENCY_CLIENTS_STORE, Supabase,
    and Google Drive with a canonical ID, proper AM assignment, and returns (cid, client_dict)."""
    global AGENCY_CLIENTS_STORE
    if not client_input:
        cid = current_client_id()
        c = next((cl for cl in AGENCY_CLIENTS_STORE if cl.get("id") == cid), None)
        return cid, c or {"id": cid, "name": _client_name(cid)}

    client_str = str(client_input).strip()
    
    # 1. Search existing clients by exact ID, name, or company
    target = None
    for c in AGENCY_CLIENTS_STORE:
        if not isinstance(c, dict):
            continue
        c_id = str(c.get("id") or "").strip()
        c_name = str(c.get("name") or "").strip()
        c_comp = str(c.get("company") or "").strip()
        if c_id == client_str or c_name.lower() == client_str.lower() or (c_comp and c_comp.lower() == client_str.lower()):
            target = c
            break
            
    if target:
        if am_id:
            target["am_employee_id"] = am_id
            target["am_name"] = "آيه أحمد مجاهد" if am_id in ("EMP-5887-5256", "AM-5887-5256") else ("محمود خالد" if am_id in ("AM-2072-9827", "EMP-2072-9827") else target.get("am_name", "محمود خالد"))
            push_setting("meta_ai_clients", AGENCY_CLIENTS_STORE)
        elif not target.get("am_name"):
            t_amid = target.get("am_employee_id") or "AM-2072-9827"
            target["am_name"] = "آيه أحمد مجاهد" if t_amid in ("EMP-5887-5256", "AM-5887-5256") else "محمود خالد"
        return str(target.get("id")), target

    # 2. Create new client record
    effective_amid = am_id or _my_employee_id() or "AM-2072-9827"
    effective_amname = "آيه أحمد مجاهد" if effective_amid in ("EMP-5887-5256", "AM-5887-5256") else "محمود خالد"
    slug = re.sub(r"[^\w\u0600-\u06FF]", "", client_str.replace(" ", "_"))[:20].lower()
    new_cid = f"cli_{slug}_{int(time.time())}" if slug else f"cli_{int(time.time())}"
    new_client = {
        "id": new_cid,
        "name": client_str,
        "company": client_str,
        "package": "Business VIP",
        "am_employee_id": effective_amid,
        "am_name": effective_amname,
        "page_id": None,
        "ig_id": None,
        "status": "active",
        "is_active": True,
        "fb_connected": False,
        "ig_connected": False,
        "created_at": datetime.now(timezone.utc).isoformat()
    }
    AGENCY_CLIENTS_STORE.append(new_client)
    push_setting("meta_ai_clients", AGENCY_CLIENTS_STORE)
    
    try:
        import threading
        threading.Thread(target=client_drive_folder_id, args=(new_cid,), daemon=True).start()
    except Exception:
        pass
        
    return new_cid, new_client


def client_drive_folder_id(cid):
    """Get-or-create EXACTLY ONE canonical Drive folder for this client inside CLIENTS_ROOT_FOLDER_ID."""
    folders = cache.get("client_folders") or {}
    fid = folders.get(str(cid))
    if fid:
        return fid
    cname = _client_name(cid)
    # Search Google Drive directly to avoid duplicate folder creation across lambdas
    existing_fid = _drive_find_folder_by_name(CLIENTS_ROOT_FOLDER_ID, cname)
    if existing_fid:
        folders[str(cid)] = existing_fid
        cache["client_folders"] = folders
        return existing_fid

    token = get_google_oauth_access_token()
    if not token:
        return None
    name = f"Domya — {cname}"
    try:
        meta = {"name": name, "mimeType": "application/vnd.google-apps.folder", "parents": [CLIENTS_ROOT_FOLDER_ID]}
        req = urllib.request.Request(
            "https://www.googleapis.com/drive/v3/files?fields=id",
            data=json.dumps(meta).encode("utf-8"),
            headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"})
        fid = json.loads(urllib.request.urlopen(req, timeout=15).read()).get("id")
        if not fid:
            return None
        _drive_set_anyone_reader(token, fid)
        folders[str(cid)] = fid
        cache["client_folders"] = folders
        push_setting("meta_ai_client_folders", folders)
        return fid
    except Exception as e:
        print(f"[client folder] {e}")
        return None


def client_month_folder_id(cid, month=None):
    """Get-or-create a monthly subfolder (YYYY-MM) inside the client's Drive folder."""
    parent = client_drive_folder_id(cid)
    if not parent:
        return None
    if not month:
        try:
            month = _cairo_now().strftime("%Y-%m")
        except Exception:
            month = datetime.now(timezone.utc).strftime("%Y-%m")
    key = f"{cid}:{month}"
    mf = cache.get("client_month_folders") or {}
    if mf.get(key):
        return mf[key]
    existing_fid = _drive_find_folder_by_name(parent, month)
    if existing_fid:
        mf[key] = existing_fid
        cache["client_month_folders"] = mf
        return existing_fid
    token = get_google_oauth_access_token()
    if not token:
        return parent
