def drive_resumable_session(name, mime, parent_id=None, origin=None):
    """Start a resumable upload session; returns the session URL the browser PUTs to
    (no OAuth token is exposed to the browser). Includes CORS Origin so browser PUTs succeed."""
    token = get_google_oauth_access_token()
    if not token:
        return None
    meta = {"name": name}
    if parent_id:
        meta["parents"] = [parent_id]
    try:
        hdrs = {
            "Authorization": f"Bearer {token}",
            "Content-Type": "application/json; charset=UTF-8",
            "X-Upload-Content-Type": mime or "application/octet-stream"
        }
        if origin:
            hdrs["Origin"] = origin
        req = urllib.request.Request(
            "https://www.googleapis.com/upload/drive/v3/files?uploadType=resumable&fields=id",
            data=json.dumps(meta).encode("utf-8"),
            headers=hdrs)
        with urllib.request.urlopen(req, timeout=15) as resp:
            return resp.headers.get("Location")
    except Exception as e:
        print(f"[resumable session] {e}")
        return None

def drive_upload_bytes(name, data, mime, parent_url=None, parent_id=None, parent_ids=None):
    """Upload raw bytes to Drive (multipart), make it link-readable, return a shareable URL.
    Also creates direct Shortcuts in any secondary folders (e.g. Client Monthly folder)."""
    token = get_google_oauth_access_token()
    if not token:
        return None
    try:
        meta = {"name": name}
        pids = []
        if parent_ids and isinstance(parent_ids, (list, tuple)):
            pids = [str(p).strip() for p in parent_ids if p and str(p).strip()]
        elif parent_id:
            pids = [str(parent_id).strip()]
        elif parent_url:
            pid = drive_file_id(parent_url)
            if pid:
                pids = [pid]
                
        primary_pid = pids[0] if pids else None
        secondary_pids = pids[1:] if len(pids) > 1 else []
        
        if primary_pid:
            meta["parents"] = [primary_pid]
            
        boundary = "domya_boundary_7fbc"
        body = b""
        body += ("--" + boundary + "\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n").encode()
        body += (json.dumps(meta) + "\r\n").encode()
        body += ("--" + boundary + "\r\nContent-Type: " + mime + "\r\n\r\n").encode()
        body += data + ("\r\n--" + boundary + "--\r\n").encode()
        req = urllib.request.Request(
            "https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id",
            data=body,
            headers={"Authorization": f"Bearer {token}",
                     "Content-Type": f"multipart/related; boundary={boundary}"}
        )
        with urllib.request.urlopen(req, timeout=25) as resp:
            fid = json.loads(resp.read().decode("utf-8")).get("id")
        if not fid:
            return None
            
        # Make anyone-with-link a reader so the URL is usable
        try:
            perm = urllib.request.Request(
                f"https://www.googleapis.com/drive/v3/files/{fid}/permissions",
                data=json.dumps({"role": "reader", "type": "anyone"}).encode(),
                headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"})
            urllib.request.urlopen(perm, timeout=15).read()
        except Exception as e:
            print(f"[drive perm] {e}")

        # Automatically create shortcuts in secondary folders (e.g. Client Monthly folder)
        for sec_pid in secondary_pids:
            try:
                sc_meta = {
                    "name": name,
                    "mimeType": "application/vnd.google-apps.shortcut",
                    "parents": [sec_pid],
                    "shortcutDetails": {"targetId": fid}
                }
                sc_req = urllib.request.Request(
                    "https://www.googleapis.com/drive/v3/files?fields=id",
                    data=json.dumps(sc_meta).encode("utf-8"),
                    headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"}
                )
                urllib.request.urlopen(sc_req, timeout=10)
            except Exception as _se:
                print(f"[drive shortcut create error] {_se}")

        return f"https://drive.google.com/file/d/{fid}/view"
    except Exception as e:
        print(f"[drive upload] {e}")
        return None

