def send_telegram_bot_notification(chat_id, message_text, bot_token=None):
    tok = bot_token or _tasks_bot_token() or TELEGRAM_TASKS_BOT_TOKEN or os.environ.get("TELEGRAM_TASKS_BOT_TOKEN", "")
    if not tok or not chat_id:
        return False
    try:
        url = f"https://api.telegram.org/bot{tok}/sendMessage"
        payload = json.dumps({"chat_id": str(chat_id), "text": message_text, "parse_mode": "HTML"}).encode("utf-8")
        req = urllib.request.Request(url, data=payload, headers={"Content-Type": "application/json"})
        with urllib.request.urlopen(req, timeout=10) as resp:
            res = json.loads(resp.read().decode("utf-8"))
            return res.get("ok", False)
    except Exception as e:
        print(f"[Telegram Notification Exception] {e}")
