    target_task, cid = _find_task_any_client(task_id)
    if not target_task:
        return jsonify({"error": "المهمة غير موجودة"}), 404

    my_eid = _my_employee_id()
    is_assigned = bool(my_eid and str(target_task.get("assigned_employee_id")) == my_eid)
    can_edit_content = is_admin() or is_manager() or is_content_creator() or is_assigned or can_see_client(cid) or (session.get("role") in ("content_creator", "content", "admin", "account_manager"))
    if not can_edit_content:
        return jsonify({"error": "غير مصرح لك بتعديل محتوى ونصوص هذه المهمة"}), 403

    data = request.get_json(silent=True) or {}
    title = str(data.get("title") or "").strip()
    tagline = str(data.get("tagline") or data.get("tag_line") or "").strip()
    caption = str(data.get("caption") or data.get("description") or "").strip()
    visual_idea = str(data.get("visual_idea") or "").strip()
    post_type = str(data.get("post_type") or "post").strip().lower()
    raw_ref_links = data.get("reference_links") or []
    if isinstance(raw_ref_links, str):
        reference_links = [u.strip() for u in raw_ref_links.split(",") if u.strip()]
    elif isinstance(raw_ref_links, list):
        reference_links = [str(u).strip() for u in raw_ref_links if str(u).strip()]
    else:
        reference_links = []

    if "title" in data and title:
        target_task["title"] = title
    if "tagline" in data or "tag_line" in data:
        target_task["tagline"] = tagline
        target_task["tag_line"] = tagline
        if not title:
            target_task["title"] = tagline
    if "caption" in data or "description" in data:
        target_task["caption"] = caption
        target_task["description"] = caption
    if "visual_idea" in data:
        target_task["visual_idea"] = visual_idea
    if "design_brief" in data:
        target_task["design_brief"] = str(data.get("design_brief") or "").strip()
    if "notes" in data or "review_note" in data or "modification_request" in data:
        n_val = str(data.get("review_note") or data.get("notes") or data.get("modification_request") or "").strip()
        target_task["review_note"] = n_val
        target_task["notes"] = n_val
        target_task["modification_request"] = n_val
    if "post_type" in data and post_type:
        target_task.setdefault("content_data", {})["post_type"] = post_type
    if "reference_links" in data:
        target_task["reference_links"] = reference_links

    # Update structured data blocks
    target_task.setdefault("content_data", {})
    if "tagline" in data or "tag_line" in data:
        target_task["content_data"]["tagline"] = tagline
        target_task["content_data"]["tag_line"] = tagline
    if "caption" in data or "description" in data:
        target_task["content_data"]["caption"] = caption
    if "visual_idea" in data:
        target_task["content_data"]["visual_idea"] = visual_idea
    if "design_brief" in data:
        target_task["content_data"]["design_brief"] = str(data.get("design_brief") or "").strip()
    if "reference_links" in data:
        target_task["content_data"]["reference_links"] = reference_links

    target_task.setdefault("graphic_data", {})
    if "visual_idea" in data:
        target_task["graphic_data"]["idea"] = visual_idea
    if "design_brief" in data:
        target_task["graphic_data"]["design_brief"] = str(data.get("design_brief") or "").strip()

    target_task["updated_at"] = datetime.now(timezone.utc).isoformat()

    actor_name = current_user_rec().get("name") or current_username()
    _append_task_log(target_task, "content_updated",
                     actor_name=actor_name,
                     actor_id=_my_employee_id() or session.get("uid"),
                     actor_type=current_role(),
                     note=f"تعديل نصوص وكابشن البوست بواسطة كاتب المحتوى ({actor_name}) ️")

    save_one_task(target_task, cid)
    return jsonify({"success": True, "task": target_task, "message": "تم تحديث محتوى البوست ونصوصه بنجاح ️"})


