def _norm_plan_str(s):
    s = str(s or "").strip().lower()
    s = re.sub(r'\.(docx|doc|pdf|txt)$', '', s)
    s = re.sub(r'[\s_—\-]+', ' ', s)
    return s.strip()


@app.route("/api/plans/delete", methods=["POST", "DELETE"])
@require_manager
def api_plans_delete():
    """Delete a plan and all its tasks across Google Sheets, Supabase, and memory cache."""
    data = request.get_json(silent=True) or {}
    raw_plan_name = str(data.get("plan_name") or data.get("file_name") or "").strip()
    if not raw_plan_name:
        return jsonify({"error": "اسم الخطة مطلوب"}), 400

    target_norm = _norm_plan_str(raw_plan_name)
    all_tasks = _all_tasks_db()
    remaining = []
    deleted_tasks = []

    for t in all_tasks:
        if not isinstance(t, dict):
            continue
        p = str(t.get("plan_name") or t.get("file_name") or "").strip()
        p_norm = _norm_plan_str(p)
        # EXACT match only — never substring — to prevent accidental cross-plan deletion
        if p == raw_plan_name or p_norm == target_norm:
            deleted_tasks.append(t)
        else:
            remaining.append(t)

    # Update in-memory cache
    cache["tasks"] = remaining
    push_setting("meta_ai_tasks", remaining)

    # Save remaining tasks directly to Google Sheets Tasks tab
    _gsheet_tasks_save_all(remaining)

    # Delete from Supabase if available
    if SUPABASE_URL and SUPABASE_KEY and len(SUPABASE_URL) > 15:
        try:
            for t in deleted_tasks:
                tid = str(t.get("task_id") or t.get("id") or "")
                if tid:
                    supa_delete("mam_tasks", f"task_id=eq.{urllib.parse.quote(tid)}")
        except Exception as _e:
            print(f"[delete plan supa error] {_e}")

    return jsonify({
        "success": True,
        "ok": True,
        "message": f"تم حذف الخطة «{raw_plan_name}» وجميع مهامها ({len(deleted_tasks)} مهمة) بنجاح ️",
        "deleted_count": len(deleted_tasks),
        "plan_name": raw_plan_name
    })


@app.route("/api/plans/archive", methods=["POST"])
@require_manager
def api_plans_archive():
    """Archives all tasks of a plan so they move to the Archive and clear the active board."""
    data = request.get_json(silent=True) or {}
    raw_plan_name = str(data.get("plan_name") or data.get("file_name") or "").strip()
    if not raw_plan_name:
        return jsonify({"error": "اسم الخطة مطلوب"}), 400

    target_norm = _norm_plan_str(raw_plan_name)
    all_tasks = _all_tasks_db()
    archived_tasks = []
    updated_all = []
    now_iso = datetime.now(timezone.utc).isoformat()

    for t in all_tasks:
        if not isinstance(t, dict):
            continue
        p = str(t.get("plan_name") or t.get("file_name") or "").strip()
        p_norm = _norm_plan_str(p)
        if p == raw_plan_name or p_norm == target_norm:
            t["is_archived"] = True
            t["archived_at"] = now_iso
            _append_task_log(t, "archived",
                             actor_name=current_user_rec().get("name") or current_username(),
                             actor_id=_my_employee_id(),
                             actor_type=current_role(),
                             note=f"أرشفة الخطة: {raw_plan_name}")
            archived_tasks.append(t)
        updated_all.append(t)

    # 1. Update in-memory cache
    cache["tasks"] = updated_all

    # 2. Update Supabase
    if SUPABASE_URL and SUPABASE_KEY and len(SUPABASE_URL) > 15:
        try:
            rows_to_upsert = []
            for t in archived_tasks:
                tid = str(t.get("task_id") or t.get("id") or "")
                if tid:
                    rows_to_upsert.append({
                        "task_id": tid,
                        "client_id": str(t.get("client_id") or ""),
                        "status": str(t.get("status") or "Completed"),
                        "assigned_employee_id": str(t.get("assigned_employee_id") or "") or None,
                        "data": t
                    })
            if rows_to_upsert:
                supa_upsert("mam_tasks", rows_to_upsert)
        except Exception as _e:
            print(f"[archive plan supa error] {_e}")

    # 3. Save to Google Sheets
    try:
        _gsheet_tasks_save_all(updated_all)
    except Exception as _gs_err:
        print(f"[archive plan gsheet error] {_gs_err}")

    return jsonify({
        "success": True,
        "ok": True,
        "message": f"تمت أرشفة الخطة «{raw_plan_name}» ({len(archived_tasks)} مهمة) ونقلها للأرشيف بنجاح ",
        "archived_count": len(archived_tasks),
        "plan_name": raw_plan_name
    })


@app.route("/api/plans/unarchive", methods=["POST"])
@require_manager
def api_plans_unarchive():
    """Restores an archived plan back to the active board."""
    data = request.get_json(silent=True) or {}
    raw_plan_name = str(data.get("plan_name") or data.get("file_name") or "").strip()
