@app.route("/api/employees/workload", methods=["GET"])
@auth_guard
def api_employees_workload():
    """Active-task count and task list per employee ACROSS ALL clients — powers the real
    'who is busy' team-availability widget and employee task filter."""
    sync_from_supabase()
    counts = {}
    inprog = {}
    completed_counts = {}
    tasks_by_emp = {}
    active_statuses = {"Pending AM Approval", "Assigned", "In Progress", "Review Required", "Pending Revision", "Awaiting AM Review", "Submitted / In Review", "Submitted"}

    # Build name-to-eid and eid-to-name map from roster
    name_to_eid = {}
    eid_to_name = {}
    try:
        cfg = hr_config()
        for e in _gsheet_rows(cfg["sheet_id"], cfg["employees_gid"]):
            _id = str(e.get("employee_id") or "").strip()
            _nm = (e.get("name") or "").strip()
            if _id and _nm:
                name_to_eid[_nm] = _id
                name_to_eid[_nm.lower()] = _id
                eid_to_name[_id] = _nm
    except Exception as _e:
        print(f"[workload roster error] {_e}")

    is_adm = is_admin()
    is_mgr = is_manager()
    my_cids = set(assigned_client_ids()) if not is_adm else set()
    my_eid = _my_employee_id()

    for t in _all_tasks_db():
        if not isinstance(t, dict) or t.get("is_archived"):
            continue
        
        cid = t.get("client_id")
        # RBAC Privacy Isolation:
        # 1. Admin sees everything.
        # 2. Account Manager sees tasks for their assigned clients or tasks where they are AM.
        # 3. Regular employees only see tasks assigned to them.
        if not is_adm:
            if is_mgr:
                t_am_id = str(t.get("am_id") or "").strip()
                if cid not in my_cids and (not my_eid or t_am_id != my_eid):
                    continue
            else:
                t_emp_id = str(t.get("assigned_employee_id") or "").strip()
                if my_eid and t_emp_id != my_eid:
                    continue

        eid = str(t.get("assigned_employee_id") or "").strip()
        aname = str(t.get("assignee_name") or "").strip()
        if not eid and aname and aname in name_to_eid:
            eid = name_to_eid[aname]
        elif not eid and aname and aname.lower() in name_to_eid:
            eid = name_to_eid[aname.lower()]
        elif not eid and aname:
            # check partial match
            for r_name, r_eid in name_to_eid.items():
                if aname in r_name or r_name in aname:
                    eid = r_eid
                    break
        if not eid and aname:
            eid = aname
        if not eid:
            continue

        st = str(t.get("status") or "Assigned").strip()
        if st in active_statuses or st == "Completed":
            if st in active_statuses:
                counts[eid] = counts.get(eid, 0) + 1
                if st == "In Progress":
                    inprog[eid] = inprog.get(eid, 0) + 1
            elif st == "Completed":
                completed_counts[eid] = completed_counts.get(eid, 0) + 1

            cid = t.get("client_id")
            title_head = t.get("title") or t.get("tagline") or t.get("tag_line") or "مهمة بدون عنوان"
            tasks_by_emp.setdefault(eid, []).append({
                "task_id": t.get("task_id"),
                "title": title_head,
                "tagline": t.get("tagline") or t.get("tag_line") or title_head,
                "status": st,
                "client_id": cid,
                "client_name": _client_name(cid),
                "delivery_deadline": t.get("delivery_deadline"),
                "publish_date": t.get("publish_date"),
                "publish_time": t.get("publish_time") or "10:00",
                "scheduled_start_date": t.get("scheduled_start_date"),
                "drive_link": t.get("drive_link"),
                "notes": t.get("notes") or t.get("note"),
                "caption": t.get("caption"),
                "description": t.get("description") or t.get("caption"),
                "visual_idea": t.get("visual_idea") or (t.get("content_data") or {}).get("visual_idea") or (t.get("graphic_data") or {}).get("idea"),
                "post_type": (t.get("content_data") or {}).get("post_type") or "post",
                "review_note": t.get("review_note"),
                "timer_state": t.get("timer_state"),
                "started_at": t.get("started_at"),
                "submitted_at": t.get("submitted_at"),
                "assigned_at": t.get("assigned_at"),
                "assigned_employee_id": eid,
                "assignee_name": t.get("assignee_name") or eid_to_name.get(eid, eid),
                "am_id": t.get("am_id"),
                "am_name": t.get("am_name"),
                "file_name": t.get("file_name"),
                "plan_name": t.get("plan_name"),
                "media_urls": t.get("media_urls") or [],
                "reference_links": t.get("reference_links") or [],
                "content_data": t.get("content_data") or {},
                "graphic_data": t.get("graphic_data") or {},
                "activity_log": t.get("activity_log") or t.get("stage_history") or [],
                "kpis": t.get("kpis") or {}
            })
    return jsonify({
        "success": True,
        "workload": counts,
        "in_progress": inprog,
        "completed": completed_counts,
        "tasks_by_employee": tasks_by_emp
    })


