def _is_fake_demo_employee(eid="", nm="", role=""):
    s = f"{eid} {nm} {role}".lower()
    fake_exact = [
        "مدير الحسابات (account manager)", "مصمم الجرافيك (graphic designer)", "كاتب المحتوى (content writer)",
        "graphic designer", "content writer", "account manager", "مدير الحسابات", "مصمم الجرافيك", "كاتب المحتوى",
        "emp-001", "emp-002", "emp-003", "demo-emp", "test-emp"
    ]
    if str(nm).strip().lower() in fake_exact or str(eid).strip().lower() in fake_exact:
        return True
    if "(account manager)" in s and "محمود خالد" not in s and "آيه أحمد" not in s:
        return True
    if "(graphic designer)" in s or "(content writer)" in s or "(employee)" in s:
        return True
    return False


@app.route("/api/tasks/monthly-report", methods=["GET"])
@auth_guard
def api_tasks_monthly_report():
    sync_from_supabase()
    _cid = current_client_id()
    month_str = request.args.get("month") or datetime.now(timezone.utc).strftime("%Y-%m")
    
    roster = {}
    name_to_eid = {}
    try:
        cfg = hr_config()
        for e in _gsheet_rows(cfg["sheet_id"], cfg["employees_gid"]):
            eid = str(e.get("employee_id") or "").strip()
            nm = (e.get("name") or "").strip()
            role = str(e.get("job") or e.get("role") or "فريق العمل").strip()
            if eid and nm and not _is_fake_demo_employee(eid, nm, role):
                roster[eid] = {"name": nm, "role": role}
                name_to_eid[nm] = eid
    except Exception as _e:
        print(f"[monthly report roster] {_e}")
        
    for e in get_client_employees(_cid):
        eid = str(e.get("employee_id") or "").strip()
        nm = (e.get("name") or "").strip()
        role = str(e.get("role") or "فريق العمل").strip()
        if eid and nm and not _is_fake_demo_employee(eid, nm, role):
            if eid not in roster:
                roster[eid] = {"name": nm, "role": role}
            name_to_eid[nm] = eid

    stats = {}
    for eid, r in roster.items():
        stats[eid] = {
            "name": r["name"],
            "role": r["role"],
            "assigned": 0,
            "in_progress": 0,
            "submitted": 0,
            "completed": 0,
            "on_time": 0,
            "late": 0,
            "turnaround_hours": [],
            "durations": [],
            "notes": []
        }

    tasks = _all_tasks_db()
    for t in tasks:
        # If month_str is specified, filter tasks belonging to this month
        if month_str and month_str != "all":
            task_dates = [
                str(t.get("scheduled_start_date") or "").strip(),
                str(t.get("publish_date") or "").strip(),
                str(t.get("delivery_deadline") or "").strip(),
                str(t.get("created_at") or "").strip(),
                str(t.get("assigned_at") or "").strip(),
                str(t.get("submitted_at") or "").strip(),
            ]
            valid_dates = [d for d in task_dates if d]
            if valid_dates and not any(_matches_month(d, month_str) for d in valid_dates):
                continue

        eid = str(t.get("assigned_employee_id") or "").strip()
        nm = str(t.get("assignee_name") or "").strip()
        
        target_key = None
        if eid and eid in stats:
            target_key = eid
        elif nm and nm in name_to_eid and name_to_eid[nm] in stats:
            target_key = name_to_eid[nm]
        elif eid:
            target_key = eid
            stats[target_key] = {
                "name": nm or eid,
                "role": "فريق العمل",
                "assigned": 0,
                "in_progress": 0,
                "submitted": 0,
                "completed": 0,
                "on_time": 0,
                "late": 0,
                "turnaround_hours": [],
                "durations": [],
                "notes": []
            }
        elif nm:
            target_key = nm
            stats[target_key] = {
                "name": nm,
                "role": "فريق العمل",
                "assigned": 0,
                "in_progress": 0,
                "submitted": 0,
                "completed": 0,
                "on_time": 0,
                "late": 0,
                "turnaround_hours": [],
                "durations": [],
                "notes": []
            }

        if not target_key:
            continue

        st = str(t.get("status") or "").strip()
        # Total tasks assigned to this employee
        if st in ("Assigned", "In Progress", "Awaiting AM Review", "Submitted / In Review", "Submitted", "Completed", "Approved / Scheduled", "Done", "Review Required", "Pending Revision"):
            stats[target_key]["assigned"] += 1
            
        # Active in progress
        if st in ("In Progress", "in_progress"):
            stats[target_key]["in_progress"] += 1
            
        # Submitted by employee (Awaiting AM Review, Submitted / In Review, or Completed)
        if st in ("Awaiting AM Review", "Submitted / In Review", "Submitted", "Review Required", "Completed", "Approved / Scheduled", "Done"):
            stats[target_key]["submitted"] += 1
            
        # Approved / Completed by AM
        if st in ("Completed", "Approved / Scheduled", "Done"):
            stats[target_key]["completed"] += 1

        # KPI turnaround & on-time calculations
        kpis = t.get("kpis") or {}
        is_on_time = kpis.get("is_on_time")
        if is_on_time is None and t.get("delivery_deadline") and t.get("submitted_at"):
            dl = str(t["delivery_deadline"])[:10]
            sub = str(t["submitted_at"])[:10]
            is_on_time = (sub <= dl)
            
        if is_on_time is True:
            stats[target_key]["on_time"] += 1
        elif is_on_time is False:
            stats[target_key]["late"] += 1
            
        th = kpis.get("turnaround_hours")
        if th is None and t.get("assigned_at") and t.get("submitted_at"):
            try:
                dt_a = datetime.fromisoformat(str(t["assigned_at"]).replace("Z", "+00:00"))
                dt_s = datetime.fromisoformat(str(t["submitted_at"]).replace("Z", "+00:00"))
                th = round(max(0, (dt_s - dt_a).total_seconds()) / 3600, 2)
            except Exception:
                pass
        if th is not None and th > 0:
            stats[target_key]["turnaround_hours"].append(th)

        secs = (t.get("timer_state") or {}).get("elapsed_seconds") or 0
        if not secs:
            secs = t.get("elapsed_seconds") or 0
        if secs and secs > 0:
            stats[target_key]["durations"].append(secs / 60.0)

        note = (t.get("notes") or t.get("note") or t.get("review_note") or "").strip()
        if note and note not in (".", "-"):
            tid = t.get("task_id", "")
            stats[target_key]["notes"].append({
                "task_id": str(tid),
                "note": str(note),
                "status": str(st)
            })

    report_data = []
    for k, s in stats.items():
        if s["assigned"] > 0 or k in roster:
            durations = s["durations"]
            if durations:
                total_min = sum(durations)
                if total_min >= 60:
                    avg_dur = f"{total_min/60.0:.1f} ساعة ({int(total_min/len(durations))} د/مهمة)"
                else:
                    avg_dur = f"{int(total_min/len(durations))} دقيقة"
            else:
                avg_dur = "-"
                
            rate = f"{int((s['submitted'] / s['assigned']) * 100)}%" if s["assigned"] > 0 else "-"
            
            on_time_total = s["on_time"] + s["late"]
            on_time_rate = f"{int((s['on_time'] / on_time_total) * 100)}%" if on_time_total > 0 else "-"
            
            t_hours = s["turnaround_hours"]
            if t_hours:
                avg_th = sum(t_hours) / len(t_hours)
                avg_turnaround = f"{avg_th:.1f} ساعة" if avg_th >= 1 else f"{int(avg_th * 60)} دقيقة"
            else:
                avg_turnaround = "-"

            report_data.append({
                "employee": s["name"],
                "role": s["role"],
                "assigned": s["assigned"],
                "in_progress": s["in_progress"],
                "started": s["in_progress"] + s["submitted"],
                "submitted": s["submitted"],
                "completed": s["completed"],
                "completion_rate": rate,
                "on_time_rate": on_time_rate,
                "on_time_count": s["on_time"],
                "late_count": s["late"],
                "avg_turnaround": avg_turnaround,
                "avg_duration": avg_dur,
                "notes": s["notes"],
            })

    report_data.sort(key=lambda r: (r["submitted"], r["completed"], r["assigned"]), reverse=True)
    return jsonify({"success": True, "month": month_str, "report": report_data})


