import csv as _csv
from io import StringIO as _StringIO

def _parse_coordinate(val, fallback):
    if val is None:
        return float(fallback)
    s = str(val).strip().replace("٫", ".").replace(",", ".")
    if not s or s.lower() in ("0", "0.0", "-", "none", "null"):
        return float(fallback)
    try:
        f = float(s)
        return f if abs(f) > 0.001 else float(fallback)
    except Exception:
        return float(fallback)

# Default company sheet (Domya). Override via /api/hr/config (stored in Supabase).
_HR_DEFAULTS = {
    "sheet_id": "1Y4i5wOm85xg6Umwph0i5-5SmssAdCy0uUlqUvzQwGj0",
    "employees_gid": "1158009464",
    "attendance_gid": "2023520809",
    "payroll_gid": "253719303",
    "geofence_meters": int(os.environ.get("ATT_GEOFENCE_M", 500)),
    "company_lat": float(os.environ.get("ATT_DEFAULT_LAT", 30.469771)),
    "company_lon": float(os.environ.get("ATT_DEFAULT_LON", 31.180022)),
    "hide_location": os.environ.get("ATT_HIDE_LOCATION", "true").lower() in ("true", "1", "yes"),
    "late_after_time": os.environ.get("ATT_LATE_AFTER", "10:15"),
}

def hr_config():
    cfg = cache.get("hr_sheet")
    if not isinstance(cfg, dict):
        cfg = {}
    out = dict(_HR_DEFAULTS)
    out.update({k: v for k, v in cfg.items() if v is not None})
    # If legacy placeholder coordinates were cached, default to true HQ
    if abs(float(out.get("company_lat", 0)) - 30.0444) < 0.001:
        out["company_lat"] = float(os.environ.get("ATT_DEFAULT_LAT", 30.469771))
        out["company_lon"] = float(os.environ.get("ATT_DEFAULT_LON", 31.180022))
    return out

_GSHEET_CACHE = {}

def _gsheet_rows(sheet_id, gid, timeout=4, force_refresh=False):
    """Fetch one tab of a link-viewable Google Sheet as a list of dict rows with fast 300s in-memory TTL cache."""
    if not (sheet_id and gid):
        return []
    
    cache_key = f"{sheet_id}:{gid}"
    now = time.time()
    if not force_refresh and cache_key in _GSHEET_CACHE:
        cached_time, cached_rows = _GSHEET_CACHE[cache_key]
        if now - cached_time < 300 and cached_rows:
            return cached_rows

    url = f"https://docs.google.com/spreadsheets/d/{sheet_id}/gviz/tq?tqx=out:csv&gid={gid}"
    try:
        r = requests.get(url, timeout=timeout)
        if r.status_code != 200 or "<html" in r.text[:80].lower():
            if cache_key in _GSHEET_CACHE:
                return _GSHEET_CACHE[cache_key][1]
            return []
        r.encoding = "utf-8"
        reader = _csv.DictReader(_StringIO(r.text))
        rows = []
        for row in reader:
            rows.append({(k or "").strip(): (v or "").strip() for k, v in row.items()})
        _GSHEET_CACHE[cache_key] = (now, rows)
        return rows
    except Exception as e:
        print(f"[HR sheet fetch] {e}")
        if cache_key in _GSHEET_CACHE:
            return _GSHEET_CACHE[cache_key][1]
        return []


