def _matches_month(date_str, month_str):
    if not month_str:
        return True
    if not date_str:
        return False
    d = str(date_str).strip()
    m = str(month_str).strip()
    if d.startswith(m):
        return True
    parts = m.split("-")
    if len(parts) == 2:
        y, mm = parts[0], parts[1]
        try:
            imm = str(int(mm))
            if f"/{mm}/{y}" in d or f"-{mm}-{y}" in d or f"/{imm}/{y}" in d or f"-{imm}-{y}" in d:
                return True
        except Exception:
            pass
        if d.startswith(f"{y}/{mm}") or d.startswith(f"{y}-{mm}"):
            return True
    return False


def _sanitize_attendance_records(rows, is_admin_user=False):
    """Mask sensitive location coordinates based on ATT_HIDE_LOCATION and user role."""
    cfg = hr_config()
    hide_loc = bool(cfg.get("hide_location", True))
    out = []
    for r in rows:
        item = dict(r)
        item["notes"] = str(item.get("notes") or item.get("note") or item.get("ملاحظات") or "").strip()
        if hide_loc or not is_admin_user:
            item.pop("latitude", None)
            item.pop("longitude", None)
            d = str(item.get("distance", "")).strip()
            if d and d not in ("0", "0m", ""):
                item["distance"] = "داخل النطاق " if hide_loc else d
            else:
                item["distance"] = "—"
        out.append(item)
    return out


@app.route("/api/hr/attendance", methods=["GET"])
@require_admin
def api_hr_attendance():
    cfg = hr_config()
    # Read FRESH directly from Sheets API
    header, raw_rows = _sheets_get_all(cfg["sheet_id"], cfg["attendance_gid"])
    if header and raw_rows:
        idx = {h: i for i, h in enumerate(header)}
        rows = [{h: (r[idx[h]] if idx[h] < len(r) else "") for h in header} for r in raw_rows]
    else:
        rows = _gsheet_rows(cfg["sheet_id"], cfg["attendance_gid"], force_refresh=True)
    month = (request.args.get("month") or "").strip() # YYYY-MM
    emp_id = (request.args.get("employee_id") or "").strip()
    status_filter = (request.args.get("status") or "").strip()
    
    if month:
        rows = [r for r in rows if _matches_month(r.get("date", ""), month)]
    if emp_id:
        rows = [r for r in rows if str(r.get("employee_id", "")).strip() == emp_id]
    if status_filter:
        rows = [r for r in rows if str(r.get("status", "")).strip() == status_filter]
        
    total_hours = 0.0
    present_count = 0
    late_count = 0
    absent_count = 0
    
    for r in rows:
        st = str(r.get("status", "")).strip()
        if "حاضر" in st:
            present_count += 1
        elif "متأخر" in st or "تاخير" in st:
            late_count += 1
        elif "غياب" in st:
            absent_count += 1
            
        hrs_val = str(r.get("hours", "")).strip()
        if not hrs_val and r.get("checkin_time") and r.get("checkout_time"):
            try:
                t1 = datetime.strptime(str(r["checkin_time"]).strip(), "%H:%M:%S")
                t2 = datetime.strptime(str(r["checkout_time"]).strip(), "%H:%M:%S")
                diff_sec = max(0, (t2 - t1).total_seconds())
                hrs_val = f"{diff_sec / 3600.0:.1f}"
                r["hours"] = hrs_val
            except Exception:
                pass
        if hrs_val:
            try:
                total_hours += float(hrs_val.replace(",", "."))
            except Exception:
                pass
                
    # Sort newest date + time first
    rows.sort(key=lambda r: (str(r.get("date", "")), str(r.get("checkin_time", ""))), reverse=True)
    sanitized_rows = _sanitize_attendance_records(rows, is_admin())
    
    return jsonify({
        "success": True,
        "month": month,
        "attendance": sanitized_rows,
        "total": len(sanitized_rows),
        "summary": {
            "total": len(rows),
            "present": present_count,
            "late": late_count,
            "absent": absent_count,
            "total_hours": round(total_hours, 1)
        }
    })


