# Employee onboarding + self-service portal
# - Admin/AM creates a portal account for each real company employee
# (from the Google Sheet) and Telegram-DMs them their link + login.
# - Employees sign in and see ONLY their own tasks + attendance.
# ============================================================
PORTAL_URL = os.environ.get("PORTAL_URL", "https://metaaimoderator.vercel.app")

def _emp_username(emp):
    # Stable, simple username = the employee id from the sheet.
    return str(emp.get("employee_id") or "").strip()

def _my_employee_id():
    """The sheet employee_id linked to the logged-in portal user (if any)."""
    rec = current_user_rec() or {}
    eid = str(rec.get("employee_id") or "").strip()
    if not eid:
        uid = str(session.get("uid") or "").strip()
        if uid.startswith("EMP-") or uid.startswith("AM-"):
            return uid
        # Check if username or name matches an employee in sheet
        nm = str(rec.get("name") or rec.get("username") or session.get("username") or "").strip()
        if nm:
            cfg = hr_config()
            try:
                for e in _gsheet_rows(cfg["sheet_id"], cfg["employees_gid"]):
                    if (e.get("name") or "").strip() == nm or (e.get("username") or "").strip() == nm:
                        return str(e.get("employee_id") or "").strip()
            except Exception:
                pass
    return eid


