@app.route("/api/employees/onboard", methods=["POST"])
@require_manager
def api_employees_onboard():
    """Create portal accounts for company employees and DM each their link + credentials
    via the tasks Telegram bot. Body: {employee_ids?: [...], resend?: bool}.
    If employee_ids omitted, onboards every sheet employee that has a telegram_id."""
    sync_from_supabase()
    data = request.get_json() or {}
    only = set(str(x) for x in (data.get("employee_ids") or []))
    # Which parts of the Telegram message to send. Admin picks these in the UI.
    inc = data.get("include") or {}
    send_link = inc.get("link", True)
    send_username = inc.get("username", True)
    send_password = inc.get("password", True)
    custom_note = (data.get("custom_note") or "").strip()
    cfg = hr_config()
    sheet_emps = list(_gsheet_rows(cfg["sheet_id"], cfg["employees_gid"]))
    # include manually-added employees (added from the dashboard) that aren't in the sheet
    _sheet_ids = {str(e.get("employee_id") or "").strip() for e in sheet_emps}
    for e in get_client_employees(current_client_id()):
        if str(e.get("employee_id") or "").strip() not in _sheet_ids:
            sheet_emps.append(e)
    results = []
    for e in sheet_emps:
        eid = str(e.get("employee_id") or "").strip()
        if not eid or (only and eid not in only):
            continue
        tg = str(e.get("telegram_id") or "").replace(".0", "").strip()
        name = e.get("name") or eid
        job = (e.get("job") or "").strip().lower()
        # Role by job: account managers → account_manager; everyone else (designers,
        # writers, editors, content…) → employee (sees ONLY their own tasks/attendance).
        is_am = ("account manager" in job or "أكونت" in job or "الحسابات" in job or eid.startswith("AM-"))
        role = "account_manager" if is_am else "employee"
        username = eid
        rec = USERS_DB.get(username) or {}
        # Password policy on onboard/resend:
        # - reuse the stored plaintext if we have it (so the value stays stable), else
        # - generate a fresh one ONLY when we're actually going to send it, else
        # - leave the account's current password completely untouched.
        # This prevents silently resetting a password we never deliver → "password wrong".
        existing_plain = rec.get("password_plain")
        if existing_plain:
            password = existing_plain
        elif send_password:
            password = secrets.token_urlsafe(6)
        else:
            password = None
        # honour a role the admin set manually in the Permissions tab
        if rec.get("role_source") == "manual" and rec.get("role"):
            role = rec["role"]
        # AMs see all clients by default so their board isn't empty (admin can narrow later).
        assigned = rec.get("assigned_clients", [])
        if is_am and not assigned:
            assigned = [c.get("id") for c in AGENCY_CLIENTS_STORE if c.get("id")]
        rec.update({
            "username": username, "role": role,
            "email": e.get("email", ""), "employee_id": eid, "name": name,
            "assigned_clients": assigned,
            "created_at": rec.get("created_at") or datetime.now(timezone.utc).isoformat(),
        })
        # Only (re)write the password when we generated/reused one; never wipe an existing one.
        if password:
            rec["password"] = hash_password(password)
            rec["password_plain"] = password
        USERS_DB[username] = rec
        sent = False
        if tg:
            lines = [f" أهلاً <b>{name}</b>", ""]
            if custom_note:
                lines += [custom_note, ""]
            else:
                lines += ["ده حسابك على بوابة دوميه لمتابعة مهامك وحضورك:", ""]
            if send_link:
                lines.append(f" {PORTAL_URL}")
            if send_username:
                lines.append(f" اسم المستخدم: <code>{username}</code>")
            if send_password and password:
                lines.append(f" كلمة المرور: <code>{password}</code>")
            lines += ["", "سجّل دخولك وهتلاقي المهام المسندة ليك "]
            msg = "\n".join(lines)
            sent = bool(send_telegram_bot_notification(tg, msg))
        results.append({"employee_id": eid, "name": name, "role": role,
                        "username": username, "password": password if not tg else None,
                        "telegram_sent": sent, "has_telegram": bool(tg)})
    push_setting("meta_ai_users", USERS_DB)
    return jsonify({"ok": True, "onboarded": len(results), "results": results})


@app.route("/api/me/tasks", methods=["GET"])
@auth_guard
def api_my_tasks():
    """Tasks assigned to the logged-in employee, across all clients."""
    sync_from_supabase()
    eid = _my_employee_id()
    uname = current_username()
    if is_manager() and not eid:
        return jsonify({"tasks": [], "note": "manager"}), 200
    all_tasks = _all_tasks_db()
    mine = []
    user_rec = current_user_rec() or {}
    my_name = (user_rec.get("name") or uname or "").strip()
    
    for t in all_tasks:
        if not isinstance(t, dict):
            continue
        t_eid = str(t.get("assigned_employee_id") or "").strip()
        t_aname = str(t.get("assignee_name") or "").strip()
        
        # Match by employee_id (e.g. EMP-8986-4947)
        if eid and t_eid and t_eid == str(eid).strip():
            mine.append(t)
            continue
        # Match by name or substring (e.g. "راما ممدوح سرج" / "راما")
        if my_name and t_aname:
            if my_name == t_aname or my_name in t_aname or t_aname in my_name:
                mine.append(t)
                continue
        # Match by username
        if uname and (uname == t_eid or uname == t_aname):
            mine.append(t)
            continue
            
    mine.sort(key=_natural_task_sort_key)
    return jsonify({"tasks": mine, "employee_id": eid})


@app.route("/api/tasks/reindex-and-sort", methods=["POST", "GET"])
@auth_guard
def api_tasks_reindex_and_sort():
    """Apply natural sequential sorting to all existing tasks across all clients in DB & cache."""
    sync_from_supabase()
    all_clients = list(AGENCY_CLIENTS_STORE)
    reindexed_count = 0
    client_ids = set()
    for c in all_clients:
        cid = str(c.get("id") or c.get("client_id") or "").strip()
        if cid:
            client_ids.add(cid)
            
    # Also grab distinct client_ids from cache
    for t in (cache.get("tasks") or []):
        if isinstance(t, dict) and t.get("client_id"):
            client_ids.add(str(t.get("client_id")).strip())
            
    for cid in client_ids:
        c_tasks = get_client_tasks(cid)
        if c_tasks:
            # Group tasks by plan inside this client so every plan starts from 1..N
            by_plan = {}
            for t in c_tasks:
                pkey = str(t.get("plan_name") or t.get("file_name") or "خطة عامة").strip()
                by_plan.setdefault(pkey, []).append(t)
            
            for pkey, ptasks in by_plan.items():
                ptasks.sort(key=_natural_task_sort_key)
                for idx, task in enumerate(ptasks, 1):
                    task["post_number"] = idx
                    if not task.get("delivery_deadline") and task.get("publish_date"):
                        task["delivery_deadline"] = task.get("publish_date")
            
            c_tasks.sort(key=_natural_task_sort_key)
            save_client_tasks(c_tasks, cid)
            reindexed_count += len(c_tasks)
            
    return jsonify({
        "success": True,
        "ok": True,
        "message": f"تم تطبيق الترقيم الداخلي لكل خطة والترتيب بنجاح على {reindexed_count} مهمة في قاعدة البيانات ",
        "reindexed_count": reindexed_count,
        "clients_count": len(client_ids)
    })


@app.route("/api/me/attendance", methods=["GET"])
@auth_guard
def api_my_attendance():
    """The logged-in employee's own attendance rows from the company sheet."""
    try:
        eid = _my_employee_id()
        if not eid:
            return jsonify({"attendance": [], "note": "no linked employee_id", "total": 0})
        cfg = hr_config()
        
        # Read FRESH directly from Sheets API to avoid GViz CDN caching lag
        header, raw_rows = _sheets_get_all(cfg["sheet_id"], cfg["attendance_gid"])
        if header and raw_rows:
            idx = {h: i for i, h in enumerate(header)}
            rows = []
            for r in raw_rows:
                row_dict = {h: (r[idx[h]] if idx[h] < len(r) else "") for h in header}
                if str(row_dict.get("employee_id", "")).strip() == eid:
                    rows.append(row_dict)
        else:
            rows = [r for r in _gsheet_rows(cfg["sheet_id"], cfg["attendance_gid"], force_refresh=True)
                    if str(r.get("employee_id", "")).strip() == eid]
                    
        month = (request.args.get("month") or "").strip()
        if month:
            rows = [r for r in rows if _matches_month(r.get("date", ""), month)]
        rows.sort(key=lambda r: str(r.get("date", "")), reverse=True)
        sanitized_rows = _sanitize_attendance_records(rows, is_admin())
        return jsonify({"attendance": sanitized_rows, "employee_id": eid, "total": len(sanitized_rows)})
    except Exception as e:
        print(f"[api_my_attendance error] {e}")
        return jsonify({"attendance": [], "error": str(e), "total": 0}), 200


@app.route("/api/me/attendance/note", methods=["POST"])
@auth_guard
def api_my_attendance_note():
    try:
        data = request.get_json(silent=True) or {}
        eid = _my_employee_id()
        if not eid and is_admin():
            eid = str(data.get("employee_id") or "EMP-8086-4520").strip()
        if not eid:
            return jsonify({"ok": False, "error": "حسابك غير مربوط بكود موظف في شيت الموارد البشرية"}), 400
            
        note_text = str(data.get("note") if data.get("note") is not None else (data.get("notes") or "")).strip()
            
        cfg = hr_config()
        today, now_t = _cairo_now_parts()
        target_date = str(data.get("date") or today).strip()[:10]
        
        ok = _sheets_update_match(cfg["sheet_id"], cfg["attendance_gid"],
                                  {"employee_id": eid, "date": target_date},
                                  {"notes": note_text, "note": note_text, "ملاحظات": note_text})
        if not ok:
            emp_info = _sheet_emp(eid)
            ok = _sheets_append(cfg["sheet_id"], cfg["attendance_gid"],
                ["employee_id", "date", "name", "checkin_time", "checkout_time", "hours", "latitude", "longitude", "distance", "status", "notes"],
                {"employee_id": eid, "date": target_date, "name": emp_info.get("name", eid),
                 "checkin_time": now_t if target_date == today else "—",
                 "checkout_time": "", "hours": "0", "latitude": "0", "longitude": "0", "distance": "—",
                 "status": "حاضر", "notes": note_text})

        emp_info = _sheet_emp(eid)
        if note_text:
            try:
                _att_notify_owner(f"📝 ملاحظة حضور ({target_date}) عبر البوابة من {emp_info.get('name', eid)}:\n«{note_text}»")
            except Exception as _ne:
                print(f"[att notify error] {_ne}")
        return jsonify({"ok": True, "message": "تم حفظ الملاحظة بنجاح", "note": note_text})
    except Exception as e:
        print(f"[api_my_attendance_note error] {e}")
        return jsonify({"ok": False, "error": f"تعذّر حفظ الملاحظة: {str(e)}"}), 200


@app.route("/api/tasks/<task_id>/assign", methods=["POST", "PUT"])
@require_manager
def api_tasks_assign(task_id):
    """AM/admin assigns a task to a real employee and DMs them on Telegram."""
    t, cid = _find_task_any_client(task_id)
    if not t:
        return jsonify({"error": "المهمة غير موجودة"}), 404
    if not can_see_client(cid):
        return jsonify({"error": "غير مصرح"}), 403

    data = request.get_json(silent=True) or {}
    emp_id = str(data.get("employee_id") or "").strip()
    if not emp_id:
        return jsonify({"error": "اختر موظفاً"}), 400

    emp_info = _sheet_emp(emp_id)
    emp_name = emp_info.get("name") or emp_id
    tg = str(emp_info.get("telegram_id", "")).replace(".0", "").strip()

    t["assigned_employee_id"] = emp_id
    t["assignee_name"] = emp_name
    t["status"] = "Assigned"
    t["assigned_at"] = datetime.now(timezone.utc).isoformat()
    _append_task_log(t, "assigned",
                     actor_name=current_user_rec().get("name") or current_username(),
                     actor_type="account_manager",
                     target_emp_id=emp_id,
                     target_emp_name=emp_name,
                     note=f"إسناد المهمة إلى الموظف: {emp_name}",
                     details={"delivery_deadline": t.get("delivery_deadline"), "publish_date": t.get("publish_date")})
    save_one_task(t, cid)

    # Send an INTERACTIVE task card (start/submit buttons) — same actions as the website.
    sent = False
    if tg:
        try:
            sent = bool(send_task_to_employee(t, cid))
        except Exception as _e:
            print(f"[send_task_to_employee error] {_e}")
        if not sent:
            # Fallback to direct text message with portal link if interactive buttons failed
            portal = os.environ.get("PORTAL_URL", "https://metaaimoderator.vercel.app").rstrip("/")
            deadline = t.get("delivery_deadline") or t.get("publish_date") or "غير محدد"
            cname = _client_name(cid)
            msg = (f" <b>تم إسناد مهمة جديدة لك!</b>\n"
                   f" الموظف: {emp_name}\n"
                   f" المهمة: <b>{t.get('title','')}</b>\n"
                   f" العميل: {cname}\n"
                   f" موعد التسليم: {deadline}\n"
                   f" افتح بوابتي لبدء العمل والتسليم: {portal}/#myportal")
            sent = bool(send_telegram_bot_notification(tg, msg))
    return jsonify({"ok": True, "task": t, "telegram_sent": sent})


@app.route("/api/tasks/<task_id>/resend", methods=["POST", "PUT"])
@require_manager
def api_task_resend(task_id):
    """Re-send the interactive task card to the currently-assigned employee."""
    t, cid = _find_task_any_client(task_id)
    if not t:
        return jsonify({"error": "المهمة غير موجودة"}), 404
    if not can_see_client(cid):
        return jsonify({"error": "غير مصرح"}), 403
    if not t.get("assigned_employee_id"):
        return jsonify({"error": "المهمة مش مُسندة لحد"}), 400
    # refresh the display name from the sheet (older assigns stored just the id)
    nm = _sheet_emp(t.get("assigned_employee_id")).get("name", "")
    if nm and t.get("assignee_name") != nm:
        t["assignee_name"] = nm
        save_one_task(t, cid)
    sent = bool(send_task_to_employee(t, cid))
    return jsonify({"ok": True, "telegram_sent": sent})


@app.route("/api/tasks/<task_id>/recall", methods=["POST", "PUT"])
@require_manager
def api_task_recall(task_id):
    """AM/admin pulls back (recalls) a task from the currently assigned employee."""
    sync_from_supabase()
    t, cid = _find_task_any_client(task_id)
    if not t:
        return jsonify({"error": "المهمة غير موجودة"}), 404
    if not can_see_client(cid):
        return jsonify({"error": "غير مصرح"}), 403
    
    data = request.get_json(silent=True) or {}
    reason = (data.get("reason") or "").strip()
    
    prev_emp_id = t.get("assigned_employee_id")
    prev_emp_name = t.get("assignee_name") or prev_emp_id
    
    # Stop timer if running
    ts = t.get("timer_state") or {}
    if ts.get("is_running") and ts.get("last_start"):
        try:
            ts["elapsed_seconds"] = (ts.get("elapsed_seconds") or 0) + int(
                (datetime.now(timezone.utc) - datetime.fromisoformat(ts["last_start"])).total_seconds())
        except Exception:
            pass
    ts["is_running"] = False
    ts["last_start"] = None
    t["timer_state"] = ts

    # Record recall in stage history & activity log
    _append_task_log(t, "recalled",
                     actor_name=current_user_rec().get("name") or current_username(),
                     actor_type="account_manager",
                     target_emp_id=prev_emp_id,
                     target_emp_name=prev_emp_name,
                     note=f"سحب المهمة من: {prev_emp_name}" + (f" · السبب: {reason}" if reason else ""),
                     details={"reason": reason, "from_employee_id": prev_emp_id, "from_employee_name": prev_emp_name})
    
    # Notify previous employee via telegram if assigned
    if prev_emp_id:
        emp = _sheet_emp(prev_emp_id)
        tg = str((emp or {}).get("telegram_id", "")).replace(".0", "").strip()
        if tg:
            msg = f"️ <b>تم سحب المهمة</b>\n {t.get('title','')}\n {_client_name(cid)}\nقام مدير الحساب بسحب المهمة."
            if reason:
                msg += f"\n السبب: {reason}"
            send_telegram_bot_notification(tg, msg)

    # Reset assignment & status back to unassigned
    t["assigned_employee_id"] = None
    t["assignee_name"] = ""
    t["status"] = "Pending AM Approval"
    t["recalled_at"] = datetime.now(timezone.utc).isoformat()
    
    save_one_task(t, cid)
    return jsonify({"ok": True, "task": t, "message": "تم سحب المهمة بنجاح ↩️"})


# ============================================================
# Task lifecycle (native, mirrors the n8n workflow):
# Assigned → In Progress → Awaiting AM Review → Completed / (rejected→Assigned)
# Employees act on their OWN tasks; managers review. Telegram notifies each side.
# ============================================================
def _find_task_any_client(task_id):
    """Return (task, cid) for a task id across all clients, or (None, None).
    Reads the race-safe mam_tasks table (fallback to the cache blob)."""
    for t in _all_tasks_db():
        if isinstance(t, dict) and str(t.get("task_id")) == str(task_id):
            return t, t.get("client_id")
    return None, None

def _sheet_emp(emp_id):
    cfg = hr_config()
    return next((e for e in _gsheet_rows(cfg["sheet_id"], cfg["employees_gid"])
                 if str(e.get("employee_id")) == str(emp_id)), {}) or {}

def _client_name(cid):
    return next((c.get("name") for c in AGENCY_CLIENTS_STORE if c.get("id") == cid), cid)

def _owner_chat():
    return os.environ.get("OWNER_TELEGRAM_CHAT_ID", "1693828086")


