# ============================================================
# Interactive Tasks Telegram Bot (@tasks01_bot)
# Employees act on their tasks from Telegram with buttons — the
# same actions as the website (start / submit). Managers/owner
# can delete an employee from the roster. Mirrors the web lifecycle.
# ============================================================
import urllib.request as _tq

def _tasks_bot_token():
    return os.environ.get("TELEGRAM_TASKS_BOT_TOKEN", "")

def _tasks_api(method, payload):
    tok = _tasks_bot_token()
    if not tok:
        return {}
    try:
        req = _tq.Request(f"https://api.telegram.org/bot{tok}/{method}",
                          data=json.dumps(payload).encode("utf-8"),
                          headers={"Content-Type": "application/json"})
        return json.loads(_tq.urlopen(req, timeout=12).read())
    except Exception as e:
        print(f"[tasks api {method}] {e}")
        return {}

def _tasks_send(chat_id, text, inline=None):
    p = {"chat_id": str(chat_id), "text": text, "parse_mode": "HTML"}
    if inline is not None:
        p["reply_markup"] = {"inline_keyboard": inline}
    return _tasks_api("sendMessage", p).get("ok", False)

def _tasks_edit(chat_id, message_id, text, inline=None):
    p = {"chat_id": str(chat_id), "message_id": message_id, "text": text, "parse_mode": "HTML"}
    if inline is not None:
        p["reply_markup"] = {"inline_keyboard": inline}
    return _tasks_api("editMessageText", p).get("ok", False)

def _tasks_answer(cb_id, text=""):
    _tasks_api("answerCallbackQuery", {"callback_query_id": cb_id, "text": text})

def _task_card_text(t, cid):
    st = t.get("status", "")
    st_ar = {"Assigned": "مُسندة", "In Progress": "جاري العمل",
             "Awaiting AM Review": "بانتظار المراجعة", "Completed": "مكتملة"}.get(st, st)
    name = (t.get("assignee_name") or "").strip()
    eid = str(t.get("assigned_employee_id") or "")
    if not name or name == eid:
        name = _sheet_emp(eid).get("name", name) or eid
    post_num = _resolve_post_number(t)
    lines = [
        f" <b>بوست #{post_num}</b> (<code>{t.get('task_id','')}</code>)",
        f" {name}",
        f" {_client_name(cid)}",
        f" <b>{t.get('title','')}</b>",
    ]
    vis = (t.get("visual_idea") or t.get("design_brief") or "").strip()
    if vis and vis != t.get("title") and vis != t.get("caption"):
        lines.append(f"💡 <b>فكرة التصميم / المشهد:</b>\n{vis[:250]}")
    if t.get("caption") or t.get("description"):
        c_text = (t.get("caption") or t.get("description") or "").strip()
        if c_text and c_text != t.get("title"):
            lines.append(f"📝 <b>النص / الكابشن:</b>\n{c_text[:300]}")
    deadline = t.get("delivery_deadline") or t.get("publish_date") or "-"
    lines.append(f" موعد التسليم: <b>{deadline}</b>")
    lines.append(f" الحالة: <b>{st_ar}</b>")
    return "\n".join(lines)

def _task_card_buttons(t):
    tid = t.get("task_id")
    st = t.get("status", "")
    rows = []
    if st == "Assigned":
        rows.append([{"text": " بدء العمل", "callback_data": f"ts_{tid}"}])
    elif st == "In Progress":
        rows.append([{"text": " تسليم المهمة للمراجعة", "callback_data": f"tb_{tid}"}])
    elif st == "Awaiting AM Review":
        rows.append([{"text": " بانتظار مراجعة المدير", "callback_data": "noop"}])
    elif st == "Completed":
        rows.append([{"text": "️ مكتملة", "callback_data": "noop"}])
        
    # Add Google Drive deliverable link if present
    if t.get("drive_link"):
        rows.append([{"text": "📁 ملف Google Drive", "url": t.get("drive_link")}])
        
    # Add reference links (Facebook / Pinterest / YouTube / Drive / Behance)
    refs = t.get("reference_links") or t.get("media_urls") or []
    for idx, u in enumerate(refs[:3], 1):
        if str(u).startswith("http") and u != t.get("drive_link"):
            u_low = str(u).lower()
            lbl = "📁 ملف مرجعي" if "drive.google" in u_low else \
                  "📌 Pinterest" if "pinterest" in u_low or "pin.it" in u_low else \
                  "📹 فيديو Facebook" if "facebook.com" in u_low or "fb.watch" in u_low else \
                  "📸 Instagram" if "instagram.com" in u_low else \
                  "🎬 YouTube" if "youtube.com" in u_low or "youtu.be" in u_low else \
                  f"🔗 ريفرنس {idx}"
            rows.append([{"text": f"{lbl} ↗", "url": u}])
    return rows

def send_task_to_employee(t, cid):
    """Send an interactive task card to the assigned employee's Telegram."""
    tg = _emp_chat(t.get("assigned_employee_id"))
    if not tg:
        return False
    return _tasks_send(tg, _task_card_text(t, cid), inline=_task_card_buttons(t))

def _tasks_presser_emp(tg_id):
    """Map a Telegram presser to their employee record (fresh)."""
    tg = str(tg_id).replace(".0", "").strip()
    cfg = hr_config()
    for e in _gsheet_rows(cfg["sheet_id"], cfg["employees_gid"]):
        if str(e.get("telegram_id", "")).replace(".0", "").strip() == tg:
            return e
    return {}

def _tasks_handle_callback(cbq):
    sync_from_supabase() # read latest tasks before mutating (warm-instance staleness)
    data = str(cbq.get("data", ""))
    cb_id = cbq.get("id")
    presser = str((cbq.get("from") or {}).get("id", "")).strip()
    msg = cbq.get("message") or {}
    chat_id = str((msg.get("chat") or {}).get("id", ""))
    message_id = msg.get("message_id")

    if data == "noop":
        _tasks_answer(cb_id)
        return

    # ---- delete employee (managers/owner only) ----
    if data.startswith("ed_"):
        allowed = {str(_owner_chat()).strip()}
        allowed |= {x.strip() for x in os.environ.get("OWNER_APPROVERS", "").split(",") if x.strip()}
        if presser not in allowed:
            _tasks_answer(cb_id, "غير مصرح لك")
            return
        emp_id = data[3:]
        ok = _delete_sheet_employee(emp_id)
        _tasks_answer(cb_id, "تم حذف الموظف" if ok else "تعذّر الحذف")
        if ok and message_id:
            _tasks_edit(chat_id, message_id, f"️ تم حذف الموظف <code>{emp_id}</code> من القائمة.")
        return

    # ---- task actions (start / submit) ----
    if data.startswith("ts_") or data.startswith("tb_"):
        tid = data[3:]
        t, cid = _find_task_any_client(tid)
        if not t:
            _tasks_answer(cb_id, "المهمة غير موجودة")
            return
        # only the assignee may act
        assignee_tg = _emp_chat(t.get("assigned_employee_id"))
        if presser != str(assignee_tg).strip():
            _tasks_answer(cb_id, "دي مش مهمتك")
            return
        if data.startswith("ts_"):
            if t.get("status") != "Assigned":
                _tasks_answer(cb_id, "المهمة مش في مرحلة البدء")
            else:
                t["status"] = "In Progress"
                t["started_at"] = datetime.now(timezone.utc).isoformat()
                ts = t.get("timer_state") or {"is_running": False, "elapsed_seconds": 0, "last_start": None}
                ts["is_running"] = True
                ts["last_start"] = t["started_at"]
                t["timer_state"] = ts
                _append_task_log(t, "started",
                                 actor_name=t.get("assignee_name") or "الموظف",
                                 actor_id=t.get("assigned_employee_id"),
                                 actor_type="employee",
                                 note="بدء العمل على المهمة من Telegram Bot")
                save_one_task(t, cid)
                _tasks_answer(cb_id, "بدأت الشغل ")
        else: # tb_ submit → ask for a note to the account manager first
            if t.get("status") not in ("In Progress", "Assigned", "Pending AM Approval"):
                _tasks_answer(cb_id, "المهمة مسلمة بالفعل أو قيد المراجعة")
            else:
                pend = cache.get("tasks_note_pending") or {}
                pend[str(presser)] = tid
                cache["tasks_note_pending"] = pend
                push_setting("meta_ai_tasks_note_pending", pend)
                _tasks_answer(cb_id, "اكتب ملاحظتك ")
                _tasks_send(chat_id, f" اكتب ملاحظتك أو رابط الملف للأكونت مانيجر عن «{t.get('title','')}» (أو ابعت <b>تم</b> من غير ملاحظة):")
        return
    _tasks_answer(cb_id)


def _tasks_do_submit(t, cid, note):
    """Stop the timer, mark Awaiting AM Review with the employee's note, notify the AM."""
    ts = t.get("timer_state") or {}
    if ts.get("is_running") and ts.get("last_start"):
        try:
            ts["elapsed_seconds"] = (ts.get("elapsed_seconds") or 0) + int(
                (datetime.now(timezone.utc) - datetime.fromisoformat(ts["last_start"])).total_seconds())
        except Exception:
            pass
    ts["is_running"] = False
    ts["last_start"] = None
    t["timer_state"] = ts
    t["status"] = "Awaiting AM Review"
    t["notes"] = note or "—"
    t["submitted_at"] = datetime.now(timezone.utc).isoformat()
    
    # Auto-extract Google Drive link or media url from note text
    drive_link = ""
    if note:
        url_match = re.search(r'https?://[^\s]+', note)
        if url_match:
            drive_link = url_match.group(0).rstrip('.,;:)')
            t["drive_link"] = drive_link
            t.setdefault("media_urls", [])
            if drive_link not in t["media_urls"]:
                t["media_urls"].append(drive_link)
    elif t.get("drive_link"):
        drive_link = t.get("drive_link")

    mins = round((ts.get("elapsed_seconds") or 0) / 60, 1)
    
    sub_entry = {
        "id": f"sub-{int(time.time()*1000)}",
        "submitted_at": t["submitted_at"],
        "submitted_by": t.get("assignee_name") or "الموظف",
        "employee_id": t.get("assigned_employee_id"),
        "drive_link": drive_link,
        "notes": note,
        "media_urls": list(t.get("media_urls") or []),
        "elapsed_minutes": mins
    }
    t.setdefault("submissions_history", []).append(sub_entry)

    _append_task_log(t, "submitted",
                     actor_name=t.get("assignee_name") or "الموظف",
                     actor_id=t.get("assigned_employee_id"),
                     actor_type="employee",
                     note=note or "تسليم المخرجات من Telegram Bot",
                     details={"notes": note, "drive_link": drive_link, "elapsed_minutes": mins, "submission_id": sub_entry["id"]})
    save_one_task(t, cid)
    # ping ONLY the client's account manager (it also shows in their web board).
    _notify_client_am(cid,
        f" <b>مهمة جاهزة للمراجعة</b>\n {t.get('assignee_name','')}\n {t.get('title','')}\n"
        f" {_client_name(cid)}\n️ {mins} دقيقة\n ملاحظات: {note or '—'}\n" +
        (f" رابط الدرايف: {drive_link}" if drive_link else ""))


@app.route("/api/telegram/tasks", methods=["POST"])
def telegram_tasks_webhook():
    secret = os.environ.get("TELEGRAM_TASKS_WEBHOOK_SECRET", "")
    if not secret or request.headers.get("X-Telegram-Bot-Api-Secret-Token", "") != secret:
        return jsonify({"ok": False}), 401
    try:
        update = request.get_json(force=True, silent=True) or {}
        if update.get("callback_query"):
            _tasks_handle_callback(update["callback_query"])
            return jsonify({"ok": True})
        msg = update.get("message") or {}
        chat_id = str((msg.get("chat") or {}).get("id", ""))
        text = (msg.get("text") or "").strip()
        tg_id = str((msg.get("from") or {}).get("id", ""))
        caption = (msg.get("caption") or "").strip()
        final_note = text or caption

        # Handle Telegram Video, Document, or Photo uploads directly from employees
        media_file_id = None
        media_file_name = None
        media_mime = "application/octet-stream"

        if msg.get("video"):
            v = msg["video"]
            media_file_id = v.get("file_id")
            media_file_name = v.get("file_name") or f"video_{int(time.time())}.mp4"
            media_mime = v.get("mime_type") or "video/mp4"
        elif msg.get("document"):
            doc = msg["document"]
            media_file_id = doc.get("file_id")
            media_file_name = doc.get("file_name") or f"doc_{int(time.time())}"
            media_mime = doc.get("mime_type") or "application/octet-stream"
        elif msg.get("photo"):
            ph = msg["photo"][-1]
            media_file_id = ph.get("file_id")
            media_file_name = f"photo_{int(time.time())}.jpg"
            media_mime = "image/jpeg"

        uploaded_drive_link = None
        if media_file_id:
            try:
                tok = _tasks_bot_token()
                gf_res = json.loads(_tq.urlopen(_tq.Request(f"https://api.telegram.org/bot{tok}/getFile?file_id={media_file_id}"), timeout=10).read().decode('utf-8'))
                file_path = (gf_res.get("result") or {}).get("file_path")
                if file_path:
                    raw_bytes = _tq.urlopen(_tq.Request(f"https://api.telegram.org/file/bot{tok}/{file_path}"), timeout=40).read()
                    emp_info = _tasks_presser_emp(tg_id)
                    emp_eid = emp_info.get("employee_id") or "EMP-001"
                    emp_nm = emp_info.get("name") or "الموظف"
                    parent_fid = employee_drive_folder_id(emp_eid, name=emp_nm)
                    uploaded_drive_link = drive_upload_bytes(media_file_name, raw_bytes, media_mime, parent_id=parent_fid)
            except Exception as _up_err:
                print(f"[telegram media download/drive error] {_up_err}")

        # If the employee owes a submit-note or sent a file deliverable
        pend = cache.get("tasks_note_pending") or {}
        tid = pend.pop(tg_id, None)
        if not tid and uploaded_drive_link:
            # Find the active in-progress task for this employee
            emp_info = _tasks_presser_emp(tg_id)
            emp_eid = str(emp_info.get("employee_id") or "")
            if emp_eid:
                all_t = _all_tasks_db()
                active_t = next((x for x in all_t if str(x.get("assigned_employee_id")) == emp_eid and x.get("status") in ("In Progress", "Assigned")), None)
                if active_t:
                    tid = active_t.get("task_id")

        if tid:
            cache["tasks_note_pending"] = pend
            push_setting("meta_ai_tasks_note_pending", pend)
            t, cid = _find_task_any_client(tid)
            if t and t.get("status") in ("In Progress", "Assigned", "Pending AM Approval"):
                note = "" if final_note in ("تم", "خلاص", "لا", "skip", "-", "done") else final_note
                if uploaded_drive_link:
                    t["drive_link"] = uploaded_drive_link
                    t.setdefault("media_urls", [])
                    if uploaded_drive_link not in t["media_urls"]:
                        t["media_urls"].append(uploaded_drive_link)
                _tasks_do_submit(t, cid, note)
                msg_text = " تم تسليم المهمة للأكونت مانيجر للمراجعة بنجاح!"
                if uploaded_drive_link:
                    msg_text += f"\n تم رفع الملف على Google Drive:\n{uploaded_drive_link}"
                _tasks_send(chat_id, msg_text)
            else:
                _tasks_send(chat_id, "المهمة مسلمة بالفعل أو قيد المراجعة.")
            return jsonify({"ok": True})

        if text == "/start":
            emp = _tasks_presser_emp(tg_id)
            nm = emp.get("name", "") if emp else ""
            _tasks_send(chat_id, f" أهلاً {nm}! ده بوت المهام. هتوصلك مهامك هنا وتقدر تبدأها وتسلّمها بالأزرار.\n\nافتح البوابة: {os.environ.get('PORTAL_URL','https://metaaimoderator.vercel.app')}")
        return jsonify({"ok": True})
    except Exception as e:
        print(f"[tasks webhook] {e}")
        return jsonify({"ok": True})


def _delete_sheet_employee(emp_id):
    """Delete an employee row from the employees sheet by employee_id (column A),
    and drop any manually-added copy. Returns True if a row was removed."""
    cfg = hr_config()
    sid, gid = cfg["sheet_id"], cfg["employees_gid"]
    token = get_google_oauth_access_token()
    header, rows = _sheets_get_all(sid, gid)
    removed = False
    if token and header:
        idx = {h: i for i, h in enumerate(header)}
        ei = idx.get("employee_id", 0)
        targets = [i + 1 for i, row in enumerate(rows)
                   if ei < len(row) and str(row[ei]).strip() == str(emp_id).strip()]
        if targets:
            body = [{"deleteDimension": {"range": {"sheetId": int(gid), "dimension": "ROWS",
                     "startIndex": r, "endIndex": r + 1}}} for r in sorted(targets, reverse=True)]
            try:
                req = urllib.request.Request(
                    f"https://sheets.googleapis.com/v4/spreadsheets/{sid}:batchUpdate",
                    data=json.dumps({"requests": body}).encode("utf-8"),
                    headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"})
                urllib.request.urlopen(req, timeout=20).read()
                removed = True
            except Exception as e:
                print(f"[delete emp] {e}")
    # drop manual copy in Supabase-backed store
    try:
        emps = [e for e in get_client_employees(current_client_id())
                if str(e.get("employee_id")) != str(emp_id)]
        save_client_employees(emps, current_client_id())
    except Exception:
        pass
    return removed


@app.route("/api/employees/<emp_id>", methods=["DELETE"])
@require_manager
def api_delete_employee(emp_id):
    """Remove an employee from the roster (sheet + manual)."""
    ok = _delete_sheet_employee(emp_id)
    return jsonify({"ok": ok, "removed": emp_id})


@app.route("/api/employees/<emp_id>/role", methods=["POST"])
@require_admin
def api_set_employee_role(emp_id):
    """Admin sets a company employee's PORTAL permission level. Marks it manual so
    onboarding won't override it from the job column."""
    sync_from_supabase()
    data = request.get_json() or {}
    role = (data.get("role") or "").strip()
    if role not in ("admin", "account_manager", "content_creator", "content", "employee"):
        return jsonify({"error": "صلاحية غير صحيحة"}), 400
    emp = _sheet_emp(emp_id)
    rec = USERS_DB.get(emp_id) or {}
    target_key = emp_id
    if not rec:
        for k, v in USERS_DB.items():
            if isinstance(v, dict) and str(v.get("employee_id")) == str(emp_id):
                rec = v
                target_key = k
                break
    assigned = rec.get("assigned_clients", [])
    if role == "account_manager" and not assigned:
        assigned = [c.get("id") for c in AGENCY_CLIENTS_STORE if c.get("id")]
    rec.update({
        "username": rec.get("username") or emp_id, "role": role, "role_source": "manual",
        "employee_id": emp_id, "name": rec.get("name") or emp.get("name", emp_id),
        "email": rec.get("email") or emp.get("email", ""),
        "assigned_clients": assigned if role != "admin" else [],
        "created_at": rec.get("created_at") or datetime.now(timezone.utc).isoformat(),
    })
    USERS_DB[target_key] = rec
    USERS_DB[emp_id] = rec
    push_setting("meta_ai_users", USERS_DB)
    return jsonify({"ok": True, "employee_id": emp_id, "role": role})


ALLOWED_TAB_IDS = {"inbox", "dash", "rules", "kb", "crm", "mode", "settings", "logs",
                   "scheduler", "tasks", "plan", "hr", "accounts", "analytics", "myportal"}

@app.route("/api/employees/<emp_id>/tabs", methods=["POST"])
@require_admin
def api_set_employee_tabs(emp_id):
    """Admin picks exactly which tabs this employee's account can see (checkbox list).
    Empty list = fall back to role defaults."""
    sync_from_supabase()
    data = request.get_json() or {}
    tabs = [t for t in (data.get("tabs") or []) if t in ALLOWED_TAB_IDS]
    emp = _sheet_emp(emp_id)
    rec = USERS_DB.get(emp_id) or {}
    target_key = emp_id
    if not rec:
        for k, v in USERS_DB.items():
            if isinstance(v, dict) and str(v.get("employee_id")) == str(emp_id):
                rec = v
                target_key = k
                break
    if not rec.get("role"):
        rec["role"] = "employee"
        rec["role_source"] = rec.get("role_source") or "manual"
    rec.update({
        "username": rec.get("username") or emp_id, "employee_id": emp_id,
        "name": rec.get("name") or emp.get("name", emp_id),
        "allowed_tabs": tabs,
        "created_at": rec.get("created_at") or datetime.now(timezone.utc).isoformat(),
    })
    USERS_DB[target_key] = rec
    USERS_DB[emp_id] = rec
    push_setting("meta_ai_users", USERS_DB)
    return jsonify({"ok": True, "employee_id": emp_id, "allowed_tabs": tabs})


@app.route("/api/employees/clear-demo", methods=["POST"])
def api_clear_demo_employees():
    """Purge manually-stored demo employees (role-name rows with no telegram_id).
    Auth: admin session OR X-Diag-Key header."""
    if not _diag_ok():
        return jsonify({"error": "Unauthorized"}), 401
    cid = current_client_id()
    before = get_client_employees(cid)
    kept = [e for e in before if str(e.get("telegram_id") or "").strip()]
    save_client_employees(kept, cid)
    return jsonify({"ok": True, "removed": len(before) - len(kept), "kept": len(kept)})


@app.route("/api/telegram/tasks/setup", methods=["POST"])
def telegram_tasks_setup():
    """Register (or delete) the tasks bot webhook. Auth: admin OR X-Diag-Key header."""
    if not _diag_ok():
        return jsonify({"error": "Unauthorized"}), 401
    tok = _tasks_bot_token()
    if not tok:
        return jsonify({"error": "tasks bot token not set"}), 400
    if request.args.get("action") == "delete":
        r = _tq.urlopen(f"https://api.telegram.org/bot{tok}/deleteWebhook", timeout=12).read()
        return jsonify({"ok": True, "action": "deleted", "result": json.loads(r)})
    base = os.environ.get("PORTAL_URL", "https://metaaimoderator.vercel.app").rstrip("/")
    hook = f"{base}/api/telegram/tasks"
    payload = {"url": hook, "allowed_updates": ["message", "callback_query"]}
    sec = os.environ.get("TELEGRAM_TASKS_WEBHOOK_SECRET", "")
    if sec:
        payload["secret_token"] = sec
    req = _tq.Request(f"https://api.telegram.org/bot{tok}/setWebhook",
                      data=json.dumps(payload).encode("utf-8"),
                      headers={"Content-Type": "application/json"})
    res = json.loads(_tq.urlopen(req, timeout=12).read())
    return jsonify({"ok": res.get("ok", False), "webhook": hook, "result": res})


